    var html = '<div class="bn-head"><span>实时活动' + (list.length ? ' · ' + list.length : '') + '</span><button type="button" data-bn-act="collapse" data-bn-type="">收起</button></div>';
    if (!list.length) html += '<div class="bn-empty">暂无实时活动<br><span style="font-size:12px;">通话、音乐、番茄钟、录音开始后会出现在这里；char 发来消息也会在这里闪一下。</span></div>';
    else html += list.map(function (a) { return rowHTML(a); }).join('');
