          relationshipStage: 2, characterCore: { speechStyle: '常规', emotionCore: '平淡', typingSpeed: 1000, emojiRate: 0.05 },
          emotionBoundary: { maxExcitement: 50, maxEmoji: 1, allowCrazyMode: false },
          forbiddenPatterns: ['发疯'], highFreqPhrases: ['嗯。'], controlWords: ['在看'], gentleWords: ['没事'],
