      // ── 读取 MemoryCore 全局上下文（跨APP共享）──
      const mcCtx = typeof MemoryCore !== 'undefined' ? MemoryCore.getContextSummary() : null;
      const mcMood     = mcCtx?.mood || 'neutral';
      const mcStage    = mcCtx?.stage || agentMeta.relationshipStage;
      const mcTimeOfDay = mcCtx?.timeOfDay || 'day';
      const mcFav      = mcCtx?.favorability || 70;

