      const charLastSaid   = recentMem.filter(m => m.role === charName).slice(-1)[0]?.text || '';
      const memHasSleep    = recentUserText.includes('睡') || recentUserText.includes('困') || recentUserText.includes('熬夜');
      const memHasMood     = recentUserText.includes('难受') || recentUserText.includes('烦') || recentUserText.includes('崩');
      const memHasMiss     = recentUserText.includes('想你') || recentUserText.includes('想见');
