const DUET_NOTES = ['“这首我们一起听过，我还记得那天晚上的风。”', '“前奏一响我就想起你。”', '“这首适合并肩坐着，什么都不说。”', '“你上次听到这首时，跟着哼了两句。”', '“这首我留着，只和你一起听。”'];
const duetLoad = () => { const d = _read(DUET_KEY, null); return Array.isArray(d) ? d : []; };
const duetSave = (l) => _write(DUET_KEY, l);
const duetAdd = (title, artist, by) => { const t = String(title || '').trim(); if (!t) return null; const l = duetLoad(); if (l.some((x) => x.title === t)) return l; l.push({ title: t, artist: String(artist || '').trim(), addedBy: by || '我', date: todayStr() }); duetSave(l); return l; };
const duetRemove = (title) => { const l = duetLoad().filter((x) => x.title !== title); duetSave(l); return l; };
const duetHistory = () => { const d = _read(DUET_HIST_KEY, null); return Array.isArray(d) ? d : []; };
const duetNoteFor = (title) => { const t = String(title || ''); let h = 0; for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0; return DUET_NOTES[h % DUET_NOTES.length]; };
const duetRecord = (title) => {
  const note = duetNoteFor(title);
  const h = duetHistory();
  h.unshift({ title: title, date: todayStr(), note: note, by: charName() });
  _write(DUET_HIST_KEY, h.slice(0, 30));
  return { title: title, note: note };
};
// WebAudio 合成迷你播放（复用手机里已有的 WebAudio 合成思路：本地振荡器旋律，不外链音频）
let _synth = null;
const duetPlayMini = (title) => {
  duetStopMini();
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    const ctx = new AC();
    const SCALE = [1, 9 / 8, 5 / 4, 3 / 2, 5 / 3, 2];
    let h = 0; const t = String(title || ''); for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0;
    const base = 330 + (h % 5) * 22;
    let step = 0;
    const note = () => {
      if (!_synth || _synth.ctx !== ctx) return;
      const f = base * SCALE[step % SCALE.length];
      const o = ctx.createOscillator(); const g = ctx.createGain();
      o.type = 'sine'; o.frequency.value = f;
      g.gain.setValueAtTime(0.0001, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.05);
      g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.55);
      o.connect(g); g.connect(ctx.destination);
      o.start(); o.stop(ctx.currentTime + 0.6);
      step++;
    };
    note();
    _synth = { ctx: ctx, timer: setInterval(note, 620), title: title };
  } catch (e) { return null; }
  const rec = duetRecord(title);
  return rec;
};
const duetStopMini = () => { if (_synth) { try { clearInterval(_synth.timer); } catch (e) {} try { _synth.ctx.close(); } catch (e) {} _synth = null; } };
// ── 3. 塔罗之夜（cove-tarot-companion 做法；ISC，FIX-15：接回原文，不另抽、不补造解读）──
const TAROT_NIGHT_KEY = 'tarot_night_v1';
const TAROT_MEANINGS = { '愚者': '新的开始，别怕迈出第一步。', '魔术师': '你手里已经有实现愿望的工具了。', '女祭司': '先听听内心的声音，答案在安静里。', '女皇': '丰盛与温柔正在靠近，好好照顾自己。', '皇帝': '稳住节奏，秩序会帮你把事情推向前。', '教皇': '向信任的人请教，别一个人硬扛。', '恋人': '关系里最重要的是坦诚的选择。', '战车': '方向对了就别犹豫，冲过去。', '力量': '温柔的坚持比硬碰硬更有力量。', '隐士': '独处不是冷落，是在找回自己。', '命运之轮': '转机正在路上，保持期待。', '正义': '公平会来，问心无愧就好。', '倒吊人': '换个角度看，卡住的事自有出路。', '死神': '旧的结束，是为了新的开始腾地方。', '节制': '慢慢来，平衡本身就是答案。', '恶魔': '看清执念，它就困不住你了。', '高塔': '崩塌之后，真实的东西会留下来。', '星星': '希望还在，星星一直都在。', '月亮': '不安只是雾，雾会散的。', '太阳': '好日子在前面，尽情期待吧。', '审判': '放下过去，你可以重新开始。', '世界': '这一程圆满了，下一程会更好。' };
const tarotReading = (cards) => {
  const list = Array.isArray(cards) ? cards : [];
  if (!list.length) return '';
  const labels = ['思想', '情感', '行为'];
  let out = '今晚的牌这样说——\n';
  list.forEach((c, i) => {
    const name = (c && (c.name || c.card)) || '';
    const rev = !!(c && (c.reversed || c.isReversed));
    const base = TAROT_MEANINGS[name] || ('在' + name.replace(/^(权杖|圣杯|宝剑|星币)/, '') + '的领域里，变化正在发生，顺势而为就好。');
    out += (labels[i] || ('第' + (i + 1) + '张')) + ' · ' + name + (rev ? '（逆位）' : '') + '：' + (rev ? '这股能量有点受阻，别急，先稳住自己。' : '') + base + '\n';
  });
  out += '总的来说：牌面没有坏消息，只有提醒。今晚早点睡，明天会更顺。';
  return out;
};
const tarotNightDue = (nowMs) => {
  const now = new Date(nowMs || Date.now());
  if (now.getHours() < 20) return false;
  const st = _read(TAROT_NIGHT_KEY, null) || {};
  return st.lastInviteDate !== todayStr(now);
};
const tarotNightMark = (nowMs) => { const st = _read(TAROT_NIGHT_KEY, null) || {}; st.lastInviteDate = todayStr(new Date(nowMs || Date.now())); _write(TAROT_NIGHT_KEY, st); return st; };
const maybeTarotInvite = (nowMs) => {
  if (window.GroupAZ && !window.GroupAZ.behaviorEnabled('tarot')) return false;
  if (!tarotNightDue(nowMs)) return false;
  if (isFocusSilent(nowMs)) return false;
  const name = charName();
  const ok = _pushToCharSession('今晚塔罗之夜，要不要一起抽三张牌？我陪你。点开塔罗 app，今晚的牌阵等你。');
  if (ok) tarotNightMark(nowMs);
  return ok;
};
const deliverTarotResult = (payload) => {
  // [GROUP-FIX15] 新路径：塔罗 app 传来的整局 payload（cove 做法：接回原文）。
  //   只转述本次占卜的原文（牌阵、牌名、正逆位、位置牌义、可引用的解读原文），不重新抽牌；
  //   没有解读原文时只讲牌面事实，并老实说没有解读，不编造。同一 sessionId 只送一次。
  if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
    const cards = Array.isArray(payload.cards) ? payload.cards : [];
    if (!cards.length) return null;
    if (payload.sessionId) {
      const stPrev = _read(TAROT_NIGHT_KEY, null) || {};
      if (stPrev.lastDeliveredSession === payload.sessionId) return null;
    }
    let text = '今晚的塔罗' + (payload.spreadName ? '（' + payload.spreadName + '）' : '') + '\n';
    text += '问题：' + (payload.question || '今晚的塔罗之夜') + '\n';
    cards.forEach((c) => {
      text += (c.position || '牌') + ' · ' + (c.name || '') + (c.reversed ? '（逆位）' : '') + (c.meaning ? '：' + c.meaning : '') + '\n';
    });
    if (payload.readingText) {
      text += '原解读（' + (payload.readingLabel || '本地牌义') + '）：' + '\n' + payload.readingText + '\n';
      if (payload.readingAiText) text += '【AI 综合解读】' + '\n' + payload.readingAiText + '\n';
    } else {
      text += '这次还没点解读，所以没有解读原文；上面就是全部牌面。想听解读的话，在塔罗 app 里点「解读」。';
    }
    const ok = _pushToCharSession(text);
    if (ok && payload.sessionId) {
      const st0 = _read(TAROT_NIGHT_KEY, null) || {};
      st0.lastDeliveredSession = payload.sessionId; _write(TAROT_NIGHT_KEY, st0);
    }
    return ok ? text : null;
  }
  // 旧路径（兼容：只传牌名数组时沿用老写法；test_groupN pin 住它，塔罗 app 本身已不再走这条路）
  const list = Array.isArray(payload) ? payload : [];
  const names = list.map((c) => (c.name || (c.card && c.card.name) || '') + ((c.isReversed || c.reversed) ? '(逆)' : '')).filter(Boolean);
  if (!names.length) return null;
  const text = '今晚的塔罗：' + names.join(' · ') + '\n' + tarotReading(list.map((c) => ({ name: c.name || (c.card && c.card.name), reversed: !!(c.isReversed || c.reversed) })));
  const ok = _pushToCharSession(text);
  return ok ? text : null;
};
// ── 5. 专注陪伴（woaini 做法；放在乙游 3D 家）──
const FOCUS_LOG_KEY = 'focus_log_v1';
const FOCUS_STATE_KEY = 'focus_state_v1';
const focusLog = () => { const d = _read(FOCUS_LOG_KEY, null); return (d && typeof d === 'object') ? Object.assign({ total: 0, lastMinutes: 0, lastDate: '', days: {} }, d) : { total: 0, lastMinutes: 0, lastDate: '', days: {} }; };
const focusStatus = () => { const s = _read(FOCUS_STATE_KEY, null); return (s && s.active) ? s : null; };
const isFocusSilent = (nowMs) => { const s = focusStatus(); if (!s) return false; const now = nowMs || Date.now(); return now < (s.until || 0); };
const focusCheer = (lastMinutes) => {
  if (lastMinutes && lastMinutes > 0) return '加油！你上次专注了 ' + lastMinutes + ' 分钟，今天也一起坚持一下吧，我在旁边陪你。';
  return '加油！从第一分钟开始，我在旁边陪你，不打扰你。';
};
const focusCelebrate = (minutes) => '完成了 ' + minutes + ' 分钟专注！辛苦啦，休息一下，喝口水——我都记着呢。';
const focusStart = (minutes, nowMs) => {
  if (focusStatus()) return null;
  const m = Math.max(1, Math.min(120, minutes || 25));
  const now = nowMs || Date.now();
  const st = { active: true, minutes: m, startedAt: now, until: now + m * 60000 };
  _write(FOCUS_STATE_KEY, st);
  return { state: st, cheer: focusCheer(focusLog().lastMinutes) };
};
const focusEnd = (nowMs, done) => {
  const s = focusStatus();
  if (!s) return null;
  const now = nowMs || Date.now();
  const elapsed = Math.max(1, Math.round((now - s.startedAt) / 60000));
  const minutes = done === false ? elapsed : s.minutes;
  const log = focusLog();
  const day = todayStr(new Date(now));
  log.days[day] = (log.days[day] || 0) + minutes;
  log.total = (log.total || 0) + minutes;
  log.lastMinutes = minutes; log.lastDate = day;
  _write(FOCUS_LOG_KEY, log);
  _write(FOCUS_STATE_KEY, { active: false });
  var ruleCheer = null;
  try { if (window.CharInnerLife && window.CharInnerLife.onPomodoroDone) ruleCheer = window.CharInnerLife.onPomodoroDone(minutes); } catch (e) {}
  try { if (typeof window !== 'undefined' && window.ScriptAE && window.ScriptAE.logEvent) window.ScriptAE.logEvent('pomodoro_done', '你', '番茄专注完成：' + minutes + ' 分钟（今日累计 ' + log.days[day] + ' 分钟）。', { kind: 'focus', minutes: minutes }); } catch (e) {}
return { minutes: minutes, total: log.total, today: log.days[day], celebrate: focusCelebrate(minutes), ruleCheer: ruleCheer };
};
