  try { if (document.hidden) return; } catch (e) {}
  // [GROUP-FIXAPPS] app 打开时桌面被整窗盖住、桌宠不可见：跳过本轮物理/渲染，回桌面下一 tick 即恢复。
  //   只省 tickPet 这一路；tickSecond（番茄钟 1 秒 tick）不动。
  //   注意：必须用 typeof SystemStore——SystemStore 是顶层 const，不在 window 上，
  //   写 window.SystemStore 守卫永远不触发（全文件 window.SystemStore = 0 处）。
  try { if (typeof SystemStore !== 'undefined' && SystemStore && SystemStore.get('activeApp')) return; } catch (e) {}
  const prefs = loadPrefs();
  const petOn = prefs.petEnabled !== false && deskPetSwitchOn();
  const desk = document.getElementById('gw-desk');
  if (desk) desk.style.display = (!petOn || prefs.petMode === 'walk-only') ? 'none' : '';
  if (!petOn) { el.style.display = 'none'; return; }
  const g = petGeom();
  /* GROUP-PET: 座位不再每 tick 重置回几何座位（否则拖动的位置会被拉回去）；
     只把座位夹进活动区（FIX2 的活动区：x∈[8,maxX]，y∈[min(h-252,groundY),groundY]，不贴 dock、不遮图标）。 */
  _pet.seatX = Math.max(g.minX, Math.min(g.maxX, _pet.seatX));
  _pet.seatY = Math.max(Math.min(g.h - 252, g.groundY), Math.min(g.groundY, _pet.seatY));
  _pet.groundY = g.groundY;
  const now = Date.now();
  const rm = reducedMotion();
  el.classList.toggle('gw-reduced', rm);
  if (prefs.petMode !== _lastPetMode) {
    if (prefs.petMode === 'desk-only' || prefs.petMode === 'full') { if (_pet.mode === 'walk') _pet.mode = 'seat'; }
    if (prefs.petMode === 'walk-only') {
      if (_pet.mode === 'sit' || _pet.mode === 'seat') { _pet.mode = 'walk'; _pet.y = g.groundY; _walkUntil = now + 6000; }
    }
    _lastPetMode = prefs.petMode;
  }
