// ── 8. 三档棋力（random / rule / minimax）+ 新手保护 ──
const SKILL_KEY = 'otome_skill_v1';
const SKILL_LEVELS = ['random', 'rule', 'minimax'];
const SKILL_LABELS = { random: '随机（爱出小牌，容易赢）', rule: '规则（按牌型规则出牌）', minimax: 'minimax（本地一层前瞻，不是全树搜索）' };
const skillLoad = () => { const d = _read(SKILL_KEY, null); return (d && typeof d === 'object') ? Object.assign({ char: 'rule', ajiu: 'random' }, d) : { char: 'rule', ajiu: 'random' }; };
const skillSet = (seatId, level) => {
  if (SKILL_LEVELS.indexOf(level) < 0) return null;
  if (seatId !== 'char' && seatId !== 'ajiu') return null;
  const d = skillLoad();
  d[seatId] = level;
  _write(SKILL_KEY, d);
  return d;
};
// minimax 档：本地一层前瞻启发式——枚举能压过上家的候选出牌，
// 按“出完后剩余手牌张数最少、单张最少”打分取最优；不是全树搜索，
// 界面与注释都写清这一点。
const _minimaxChoose = (hand, last) => {
  if (!window.GroupN || !window.GroupN.ddzClassify || !window.GroupN.ddzBeats) return null;
  const G = window.GroupN;
  const cnt = {};
  (hand || []).forEach((c) => { cnt[c.v] = (cnt[c.v] || 0) + 1; });
  const cands = [];
  Object.keys(cnt).map(Number).forEach((v) => {
    const cs = hand.filter((c) => c.v === v);
    if (cs[1]) cands.push(G.ddzClassify(cs.slice(0, 2)));
    if (cs[2]) cands.push(G.ddzClassify(cs.slice(0, 3)));
    cands.push(G.ddzClassify([cs[0]]));
  });
  const legal = cands.filter((p) => p && G.ddzBeats(p, last || null));
  if (!legal.length) return null;
  const score = (p) => {
    const rest = hand.length - p.cards.length;
    const restCnt = {};
    hand.forEach((c) => { if (!p.cards.some((x) => x.id === c.id)) restCnt[c.v] = (restCnt[c.v] || 0) + 1; });
    const singles = Object.keys(restCnt).filter((k) => restCnt[k] === 1).length;
    return rest * 10 + singles;
  };
  legal.sort((a, b) => score(a) - score(b));
  return legal[0];
};
const seatDdzChoose = (seatId, hand, last) => {
  const level = (skillLoad()[seatId]) || 'rule';
  const G = window.GroupN;
  if (!G || !G.ddzAiChoose) return undefined;
  if (level === 'random') {
    const h = (hand || []).slice();
    for (let t = 0; t < 20; t++) {
      const c = h[Math.floor(Math.random() * h.length)];
      if (!c) return null;
      const p = G.ddzClassify([c]);
      if (p && G.ddzBeats(p, last || null)) return p;
    }
    return null;
  }
  if (level === 'minimax') {
    const m = _minimaxChoose(hand, last);
    if (m) return m;
    return G.ddzAiChoose(hand, last);
  }
  return G.ddzAiChoose(hand, last);
};
// 新手保护：扫雷类游戏首点必安全。当前文件里没有扫雷（grep“扫雷”0 处），
// 本函数是通用辅助，供以后扫雷类游戏调用：若首点是雷，把雷挪到别的格子。
const firstClickSafe = (cells, firstIdx) => {
  const cs = (cells || []).map((c) => ({ mine: !!c.mine }));
  if (!cs[firstIdx] || !cs[firstIdx].mine) return cs;
  const swapTo = cs.findIndex((c, i) => i !== firstIdx && !c.mine);
  if (swapTo < 0) return cs;
  cs[firstIdx].mine = false;
  cs[swapTo].mine = true;
  return cs;
};
