const b1 = push({ who: 'narr', text: '你们窝在客厅的沙发里，他泡了两杯热茶，茶香慢慢弥漫开来。', src: hasReal? 'real': 'sample'});
const b2 = push({ who: 'ta', text: '这样待着也挺好的。只要你在，哪里都是家。', src: hasReal? 'real': 'sample', expr: 'happy'});
choiceNode.choices[0].jump = a1.id; choiceNode.choices[1].jump = b1.id;
a2.next = 'end'; b2.next = 'end';
