// GROUP-MERGEDIARY · C2 —— 日记同步接口（以后接服务器时实现这里；现在全部走本地兜底） ——
// 接口约定：
//   pull() -> 手写日记数组（与 ck_diary_shelf_v1 同形）；
//   push(entry) -> { ok, synced, reason }；
//   status() -> { mode, ok, detail }。
// 现在：本地兜底——pull/push 只读写本机 localStorage，不联网，synced 恒为 false。
// 以后接服务器：实现一个 server 适配器（同一 entry 结构经 HTTPS 同步，
//   需用户在设置里填地址与凭证），在 configureServer 里替换 active；
//   未配置时 configureServer 返回 { ok:false, reason:'not_configured' }，
//   绝不谎称已同步。sasshi 本身是静态站、无服务器同步，此接口不是从 sasshi 来的。
const DiaryShelfSync = (() => {
  const HAND_KEY = 'ck_diary_shelf_v1';
  const readLocal = () => { try { const v = JSON.parse(localStorage.getItem(HAND_KEY) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; } };
  const writeLocal = (all) => { try { localStorage.setItem(HAND_KEY, JSON.stringify(all)); return true; } catch (e) { return false; } };
  const local = {
    name: 'local',
    status: () => ({ mode: 'local', ok: true, detail: '仅本机 localStorage，未接服务器' }),
    pull: () => readLocal(),
    push: (entry) => {
      const all = readLocal();
      if (!entry || !entry.id) return { ok: false, synced: false, reason: 'bad_entry' };
      const at = all.findIndex((h) => h.id === entry.id);
      if (at >= 0) all[at] = entry; else all.unshift(entry);
      if (!writeLocal(all)) return { ok: false, synced: false, reason: 'storage_unavailable' };
      return { ok: true, synced: false, reason: 'local-only' };
    }
  };
  let active = local;
  return {
    status: () => active.status(),
    pull: () => active.pull(),
    push: (entry) => active.push(entry),
    configureServer: (cfg) => {
      if (!cfg || !cfg.endpoint) return { ok: false, reason: 'not_configured', detail: '未配置服务器地址与凭证，仍走本地' };
      return { ok: false, reason: 'not_implemented', detail: '服务器同步尚未实现，先走本地兜底' };
    }
  };
})();

// GROUP-MERGEDIARY · C3 —— 日记书架 DOM 绑定（唯一一份；A1/A3/B1 三处共用） ——
// mount 时用事件委托在容器上绑一次（dataset.dsBound 防重复挂载）；
// innerHTML 重渲染不会残留旧监听（旧子节点随 innerHTML 一起丢弃）。
// 样式全部走 .ds-（见改动 D），本对象不写任何行内样式（除 --ds-cloth 这一处）。
const DiaryShelfUI = {
  fromWxStore: function (store) {
    const list = (store && Array.isArray(store.diaries)) ? store.diaries : [];
    return list.map((d) => ({ role: '', kind: 'diary', date: (d.date || '').split(' ')[0] || '未标注日期', weather: d.weather || '', text: d.content || '' }));
  },
  mount: function (container, entries, opts) {
    if (!container) return;
    const o = opts || {};
    container._ds = { entries: entries || [], opts: o };
    container._dsRead = null;
    container.innerHTML = OtomeF.diaryShelfHTML(entries || [], { readOnly: !!o.readOnly, digests: o.digests || [], showWrite: !o.readOnly });
    if (!container.dataset.dsBound) {
      container.dataset.dsBound = '1';
      container.addEventListener('click', (ev) => {
        const st = container._ds;
        if (!st) return;
        const openBtn = ev.target.closest('[data-ds-open]');
        if (openBtn) {
          const entry = st.entries[Number(openBtn.getAttribute('data-ds-open'))];
          if (!entry) return;
          if (st.opts.onOpenBook) st.opts.onOpenBook(entry);
          else DiaryShelfUI.read(container, entry, {});
          return;
        }
        if (ev.target.closest('[data-ds-write]')) { DiaryShelfUI.write(container, st.opts); return; }
        if (ev.target.closest('[data-ds-close]')) {
          const rd = container._dsRead;
          if (rd && typeof rd.onClose === 'function') { container._dsRead = null; rd.onClose(); }
          else if (st.opts.onCloseBook) st.opts.onCloseBook();
          else DiaryShelfUI.mount(container, st.entries, st.opts);
          return;
        }
        if (ev.target.closest('[data-ds-prev]')) { DiaryShelfUI._turn(container, -1); return; }
        if (ev.target.closest('[data-ds-next]')) { DiaryShelfUI._turn(container, 1); return; }
        if (ev.target.closest('[data-ds-save]')) { DiaryShelfUI._saveHand(container, st.opts); }
      });
    }
  },
  read: function (container, entry, opts) {
    if (!container || !entry) return;
    const o = opts || {};
    const r = OtomeF.diaryShelfRead(entry, 0);
    container._dsRead = { entry: entry, page: r.page, total: r.total, onClose: o.onClose || null };
    container.innerHTML = r.html;
  },
  _turn: function (container, dir) {
    const s = container._dsRead;
    if (!s) return;
    const next = s.page + dir;
    if (next < 0 || next >= s.total) return;
    const r = OtomeF.diaryShelfRead(s.entry, next);
    s.page = r.page;
    container.innerHTML = r.html;
  },
  write: function (container, opts) {
    if (!container) return;
    const o = opts || {};
    container._dsRead = null;
    const now = new Date();
    const dateStr = (now.getMonth() + 1) + '月' + now.getDate() + '日';
    container.innerHTML = '<div class="ds-editor"><div class="ds-editor-title">写一篇日记</div>'
      + '<label class="ds-editor-row">日期 <input type="text" data-ds-f="date" value="' + dateStr + '"></label>'
      + '<label class="ds-editor-row">天气 <input type="text" data-ds-f="weather" placeholder="晴 / 雨 / 阴"></label>'
      + '<label class="ds-editor-row">心情词 <input type="text" data-ds-f="mood" maxlength="10" placeholder="≤10 字，可空"></label>'
      + '<textarea data-ds-f="text" placeholder="写下来，合上就放回书架了…"></textarea>'
      + '<div class="ds-editor-err" data-ds-err hidden></div>'
      + '<div class="ds-editor-btns"><button type="button" data-ds-save="1">放回书架</button>'
      + '<button type="button" data-ds-close="1">不写了</button></div></div>';
  },
  _saveHand: function (container, opts) {
    const o = opts || {};
    const q = (k) => { const el = container.querySelector('[data-ds-f="' + k + '"]'); return el ? el.value.trim() : ''; };
    const text = q('text');
    const err = container.querySelector('[data-ds-err]');
    if (!text) {
      if (err) { err.hidden = false; err.textContent = '先写点什么，再放回书架吧。'; }
      return;
    }
    const entry = { id: 'h' + Date.now().toString(36), role: o.role || '', date: q('date'), weather: q('weather'), mood: q('mood').slice(0, 10), text: text, createdAt: Date.now(), source: 'hand' };
    const r = DiaryShelfSync.push(entry);
    if (!r.ok) {
      if (err) { err.hidden = false; err.textContent = '保存失败：浏览器存储不可用（' + (r.reason || '未知') + '），没有存下来。'; }
      return;
    }
    if (typeof o.onAfterWrite === 'function') o.onAfterWrite();
    else DiaryShelfUI.mount(container, OtomeF.diaryShelfCollect({}, {}, null, DiaryShelfSync.pull()), { readOnly: !!o.readOnly, role: o.role });
  }
};
// Live2D 真实模型接口（预留）：现在调它就诚实提示暂未接入。
// 原因：参考仓库 zziying/ai-live2d-body 是一篇架构思路文档（CC BY 4.0），
// 仓库里没有附带可用的.model3.json 模型文件；当前人物是自绘 SVG 立绘，不是 Cubism 模型。

// F组追加 · 抠图人物 + 捏声音（纯函数部分，可抽出做 Node 冒烟测试）
// 新键：otome_custom_char_v1（抠图人物列表 + 当前使用）、otome_voice_v1（捏好的声音）
Object.assign(OtomeF, (() => {
  const CHAR_KEY = 'otome_custom_char_v1';
  const VOICE_KEY = 'otome_voice_v1';
  const _rd = (k) => { try { return JSON.parse(localStorage.getItem(k) || 'null'); } catch (e) { return null; } };
  const _wr = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch (e) { return false; } };
  // —— 抠图人物 ——
  const loadCustomChars = () => { const d = _rd(CHAR_KEY); return (d && Array.isArray(d.chars)) ? d : { chars: [], activeId: '' }; };
  const saveCustomChars = (d) => _wr(CHAR_KEY, d);
  const addCustomChar = (dataUrl, name) => {
    const d = loadCustomChars();
    if (d.chars.length >= 5) return { ok: false, reason: 'full' };
    const c = { id: 'cc_' + Date.now(), name: name || ('抠图人物' + (d.chars.length + 1)), dataUrl, createdAt: Date.now() };
    d.chars.push(c);
    if (!saveCustomChars(d)) { d.chars.pop(); return { ok: false, reason: 'toobig' }; }
    return { ok: true, char: c };
  };
  const setActiveChar = (id) => { const d = loadCustomChars(); d.activeId = id || ''; saveCustomChars(d); return d; };
  const deleteCustomChar = (id) => { const d = loadCustomChars(); d.chars = d.chars.filter(c => c.id !== id); if (d.activeId === id) d.activeId = ''; saveCustomChars(d); return d; };
  const activeCustomChar = () => { const d = loadCustomChars(); return d.chars.find(c => c.id === d.activeId) || null; };
  // —— 捏声音（设备自带 speechSynthesis 调音，不是训练的真人声模型） ——
  const defaultVoice = () => ({ pitch: 1, rate: 1, volume: 1, voiceURI: '', voiceName: '', lang: 'zh-CN', muted: false });
  const clampVoice = (v) => {
    const o = Object.assign(defaultVoice(), v || {});
    const num = (x, dflt) => { const n = Number(x); return Number.isFinite(n) ? n : dflt; };
    o.pitch = Math.max(0.5, Math.min(2, num(o.pitch, 1)));
    o.rate = Math.max(0.5, Math.min(2, num(o.rate, 1)));
    o.volume = Math.max(0, Math.min(1, num(o.volume, 1)));
    o.muted = !!o.muted;
    o.voiceURI = String(o.voiceURI || '');
    o.voiceName = String(o.voiceName || '');
    o.lang = String(o.lang || 'zh-CN');
    return o;
  };
  const loadVoice = () => clampVoice(_rd(VOICE_KEY) || {});
  const saveVoice = (v) => _wr(VOICE_KEY, clampVoice(v));
  // —— 抠图：canvas 边缘漫水 + 颜色相近度 ——
  // img = { width, height, data: Uint8ClampedArray }；返回新对象（原数据不动）。
  // 种子色取四角平均；从所有边缘像素漫水扩散，颜色距离 <= tolerance 的像素变透明。
  const colorDist = (r1, g1, b1, r2, g2, b2) => Math.sqrt((r1 - r2) * (r1 - r2) + (g1 - g2) * (g1 - g2) + (b1 - b2) * (b1 - b2));
  const removeBg = (img, tolerance) => {
    const w = img.width, h = img.height, src = img.data;
    const out = new Uint8ClampedArray(src);
    const tol = Math.max(0, Math.min(200, Number(tolerance) || 0));
    const corners = [[0, 0], [w - 1, 0], [0, h - 1], [w - 1, h - 1]];
    let sr = 0, sg = 0, sb = 0;
    corners.forEach(([x, y]) => { const i = (y * w + x) * 4; sr += src[i]; sg += src[i + 1]; sb += src[i + 2]; });
    sr /= 4; sg /= 4; sb /= 4;
    const seen = new Uint8Array(w * h);
    const stack = [];
    const pushIf = (x, y) => {
      if (x < 0 || y < 0 || x >= w || y >= h) return;
      const k = y * w + x;
      if (seen[k]) return;
      seen[k] = 1;
      const i = k * 4;
      if (colorDist(src[i], src[i + 1], src[i + 2], sr, sg, sb) <= tol) stack.push(k);
    };
    for (let x = 0; x < w; x++) { pushIf(x, 0); pushIf(x, h - 1); }
    for (let y = 0; y < h; y++) { pushIf(0, y); pushIf(w - 1, y); }
    while (stack.length) {
      const k = stack.pop();
      out[k * 4 + 3] = 0;
      const x = k % w, y = (k / w) | 0;
      pushIf(x + 1, y); pushIf(x - 1, y); pushIf(x, y + 1); pushIf(x, y - 1);
    }
    return { width: w, height: h, data: out };
  };
  return { CHAR_KEY, VOICE_KEY, loadCustomChars, saveCustomChars, addCustomChar, setActiveChar, deleteCustomChar, activeCustomChar, defaultVoice, clampVoice, loadVoice, saveVoice, colorDist, removeBg };
})());

