    window.__xwParseEpubBuffer = (buf) => XwEpub.parse(buf);

   // ══════════════════════════════════════════════════════════════
   // GROUP-Q-REALFLIP · Q组：真实翻页（Ice-Paperbound 新翻页模式）
   // 出处：paper-flipbook / JohnnyWang8802 https://github.com/JohnnyWang8802/paper-flipbook
   // （MIT License；字体 SIL OFL、文字公有领域——本实现未复制其代码、未用其诗文与字体，
   // 只按其 README 的做法自己写：手写 WebGL2 卷曲页 + DOM + CSS 3D 兜底；页面纹理来自
   // 本机 DOM 光栅化 SVG foreignObject → canvas → 纹理；网格顶点弯曲改为 CPU 形变 +
   // 顶点上传，便于单测弯曲/重力/Hermite；阴影为折叠处柔和衰减 + 页下投影的近似，
   // 未做完整 2048² 方向阴影贴图 pass，见补丁头注释与汇报。）
   // 做法要点（与 paper-flipbook 对照）：
   //  · 弯曲跟 sin(πp)：curlBend(p) = sin(πp)，p=0/1 平、p=0.5 最弯；
   //  · 折叠轴随抓页面高度倾斜 ±45°：foldTiltDeg(grabH)；
   //  · 叶子绕圆柱卷曲 + 重力下垂 droop(u, p, grabH)；静止页有书脊隆起与轻微皱褶；
   //  · 松手保留手的速度：Hermite 曲线把释放速度带进下落（hermiteRelease）；
   //  · 点击翻页 0.85s 正弦缓动 + 小页角翘起；拖动跟手；
   //  · 页面纹理：DOM 分页内容 → SVG foreignObject → canvas → 纹理，提前缓存当前页与下一页；
   //  · 无 WebGL2 时走 DOM + CSS 3D 翻页兜底（rotateY），不黑屏；
   //  · 性能降档：手机网格减半（32×22）、阴影 1024；连续 5 帧 >50ms 自动切 DOM 兜底并记住；
   //  · prefers-reduced-motion 开时直接换页；aria-live 报页码。
   // 数据层不动：进度仍走 NovelReaderCore.progressForPos/globalForProgress，
   // 批注仍走 novel_annotations_v1；真实翻页只是换页的表现层。
   // ══════════════════════════════════════════════════════════════
   const RealFlip = {
       MARK: 'GROUP-Q-REALFLIP',
       flipMs: 850,
       GRID_DESKTOP: { cols: 64, rows: 44, shadow: 2048 },
       GRID_MOBILE: { cols: 32, rows: 22, shadow: 1024 },
       SLOW_DT_MS: 50,
       SLOW_FRAMES_MAX: 5,
       FLING_V: 0.4,
       TAP_PX: 8,
       COMMIT_P: 0.35,
       perfFallback: false,
       onFlipStart: null,
       onCommit: null,
       onTap: null,
       onFallback: null,
       _stage: null,
       _texCache: {},
       clamp01: function(x) { return Math.max(0, Math.min(1, x)); },
       clamp: function(x, a, b) { return Math.max(a, Math.min(b, x)); },
       // 弯曲跟 sin(πp)：p=0/1 平、p=0.5 最弯（paper-flipbook 的做法）
       curlBend: function(p) { return Math.sin(Math.PI * RealFlip.clamp01(p)); },
       // 折叠轴倾斜：抓页面顶端 -45°、底端 +45°、中间 0°
       foldTiltDeg: function(grabH) { return RealFlip.clamp((RealFlip.clamp01(grabH == null ? 0.5 : grabH) - 0.5) * 90, -45, 45); },
       // 卷曲圆柱半径（页宽单位）：越弯半径越大
       curlRadius: function(p) { return 0.10 + 0.10 * RealFlip.curlBend(p); },
       // 重力下垂：离折叠轴越远、下垂越大；抓得越低垂得越多
       droop: function(u, p, grabH) { return 0.22 * RealFlip.curlBend(p) * u * u * (0.6 + 0.8 * RealFlip.clamp01(grabH == null ? 0.5 : grabH)); },
       easeSineInOut: function(t) { return 0.5 - 0.5 * Math.cos(Math.PI * RealFlip.clamp01(t)); },
       hermite: function(p0, p1, m0, m1, t) {
           const t2 = t * t, t3 = t2 * t;
           const h00 = 2 * t3 - 3 * t2 + 1, h10 = t3 - 2 * t2 + t, h01 = -2 * t3 + 3 * t2, h11 = t3 - t2;
           return h00 * p0 + h10 * m0 + h01 * p1 + h11 * m1;
       },
       // 松手保留手的速度：v0 为释放瞬间进度/秒，带进 Hermite 下落
       hermiteRelease: function(p0, v0, p1, durMs, tMs) {
           const dur = Math.max(1, durMs || 850);
           const t = RealFlip.clamp01((tMs || 0) / dur);
           return RealFlip.hermite(p0, p1, (v0 || 0) * (dur / 1000), 0, t);
       },
       // 纯函数：下一页位置（只在书内走；跨书/到头返回 moved:false，交给原有逻辑）
       nextPos: function(pages, ci, pi, delta) {
           const list = pages || [];
           if (delta > 0) {
               const n = (list[ci] || []).length || 1;
               if (pi + 1 < n) return { chapterIdx: ci, pageIdx: pi + 1, moved: true, atStart: false, atEnd: false };
               if (ci + 1 < list.length) return { chapterIdx: ci + 1, pageIdx: 0, moved: true, atStart: false, atEnd: false };
               return { chapterIdx: ci, pageIdx: pi, moved: false, atStart: false, atEnd: true };
           }
           if (pi > 0) return { chapterIdx: ci, pageIdx: pi - 1, moved: true, atStart: false, atEnd: false };
           if (ci > 0) { const n = (list[ci - 1] || []).length || 1; return { chapterIdx: ci - 1, pageIdx: n - 1, moved: true, atStart: false, atEnd: false }; }
           return { chapterIdx: ci, pageIdx: pi, moved: false, atStart: true, atEnd: false };
       },
       reducedMotion: function() {
           try { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (e) { return false; }
       },
       isMobileViewport: function() {
           try { return (window.innerWidth || 0) <= 640 || /Mobi|Android|iPhone|iPad|Mobile/i.test(window.navigator ? window.navigator.userAgent : ''); } catch (e) { return false; }
       },
       gridForTier: function(isMobile) { return isMobile ? RealFlip.GRID_MOBILE : RealFlip.GRID_DESKTOP; },
       stageReady: function(appWin) { const st = RealFlip._stage; return !!(st && st.appWin === appWin && !st.animating); },
       isAnimating: function() { return !!(RealFlip._stage && RealFlip._stage.animating); },
       // 单个网格点的形变：x∈[0,1]（0=书脊，1=外缘），y∈[0,1]（上→下），p∈[0,1] 翻页进度，
       // dir=1 向前翻、-1 向后翻，grabH∈[0,1] 抓页面高度。返回 {x, y, z, curl}。
       // 折叠线随 p 横移、随 grabH 倾斜；折叠轴外侧的叶子绕该轴旋转 φ=πp，同时按
       // sin(πp) 卷曲、按 u² 重力下垂；p=0 恒等、p=1 叶子翻到对侧。
       deformPoint: function(x, y, p, dir, grabH) {
           p = RealFlip.clamp01(p);
           const bend = RealFlip.curlBend(p);
           const gh = RealFlip.clamp01(grabH == null ? 0.5 : grabH);
           const tilt = RealFlip.foldTiltDeg(gh) * Math.PI / 180;
           let fx = (dir > 0) ? (1 - p) : p;
           fx = fx + Math.tan(tilt) * (y - 0.5) * 0.35;
           fx = Math.max(0.05, Math.min(0.95, fx));
           const side = (dir > 0) ? (x - fx) : (fx - x);
           if (side <= 0) {
               const bulge = 0.02 * (1 - x) * Math.sin(Math.PI * y);
               const wrinkle = 0.004 * Math.sin(6 * Math.PI * x) * Math.sin(3 * Math.PI * y) * (1 - bend);
               return { x: x, y: y, z: bulge + wrinkle, curl: 0 };
           }
           const span = Math.max(0.001, (dir > 0) ? (1 - fx) : fx);
           const u = RealFlip.clamp01(side / span);
           const phi = Math.PI * p;
           const nx = fx + dir * side * Math.cos(phi);
           let z = side * Math.sin(phi);
           z += bend * RealFlip.curlRadius(p) * Math.sin(Math.PI * Math.min(u * 1.2, 1));
           z -= RealFlip.droop(u, p, gh);
           return { x: nx, y: y, z: z, curl: bend * Math.sin(Math.PI * u) };
       },
       // 页面纹理源：把读书器自己的 DOM 分页内容拼成 SVG foreignObject（无外链）
       buildPageSvg: function(title, paras, pageBg, ink, w, h) {
           const esc = function(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
           const body = (paras || []).map(function(pp) { return '<p style="font-size:34px;line-height:1.9;color:' + ink + ';text-indent:2em;margin:0 0 22px 0;">' + esc(pp) + '</p>'; }).join('');
           return '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '">'
               + '<foreignObject x="0" y="0" width="' + w + '" height="' + h + '">'
               + '<div xmlns="http://www.w3.org/1999/xhtml" style="width:' + w + 'px;height:' + h + 'px;background:' + pageBg + ';padding:52px 56px 52px 84px;box-sizing:border-box;font-family:serif;">'
               + '<div style="font-size:28px;font-weight:700;letter-spacing:4px;color:' + ink + ';margin-bottom:28px;padding-bottom:16px;border-bottom:2px dashed #a9c6d8;">' + esc(title) + '</div>'
               + body + '</div></foreignObject></svg>';
       },
       // SVG foreignObject → Image → 可上纹理的图；失败/超时一律 resolve(null)，不阻塞渲染
       rasterizePage: function(title, paras, pageBg, ink) {
           return new Promise(function(resolve) {
               let done = false;
               const finish = function(v) { if (!done) { done = true; resolve(v); } };
               setTimeout(function() { finish(null); }, 1500);
               try {
                   const svg = RealFlip.buildPageSvg(title, paras, pageBg, ink, 720, 1040);
                   const url = (window.URL && window.URL.createObjectURL) ? window.URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml;charset=utf-8' })) : null;
                   if (!url) { finish(null); return; }
                   const img = new Image();
                   img.onload = function() { try { if (window.URL.revokeObjectURL) window.URL.revokeObjectURL(url); } catch (e) {} finish(img); };
                   img.onerror = function() { finish(null); };
                   img.src = url;
               } catch (e) { finish(null); }
           });
       },
       VERT_SRC: 'attribute vec3 a_pos; attribute vec2 a_uv; attribute float a_curl; varying vec2 v_uv; varying float v_curl; void main(){ v_uv = a_uv; v_curl = a_curl; vec2 clip = vec2(a_pos.x * 2.0 - 1.0, 1.0 - a_pos.y * 2.0); gl_Position = vec4(clip.x, clip.y + a_pos.z * 0.10, 0.0, 1.0); }',
       FRAG_SRC: 'precision mediump float; varying vec2 v_uv; varying float v_curl; uniform sampler2D u_tex; uniform float u_bend; uniform float u_foldX; uniform vec3 u_paper; void main(){ vec4 tex = texture2D(u_tex, v_uv); float hemi = 0.78 + 0.22 * (1.0 - v_curl); float spec = 0.06 * v_curl; float foldDist = abs(v_uv.x - u_foldX); float shadow = 0.30 * u_bend * exp(-foldDist * 9.0); vec3 col = tex.rgb * hemi + vec3(spec); col *= (1.0 - shadow); col = mix(col, u_paper * 0.96, 0.04); gl_FragColor = vec4(col, tex.a); }',
       compileShader: function(gl, type, src) {
           try {
               const sh = gl.createShader(type);
               gl.shaderSource(sh, src);
               gl.compileShader(sh);
               if (gl.getShaderParameter && !gl.getShaderParameter(sh, gl.COMPILE_STATUS)) return null;
               return sh;
           } catch (e) { return null; }
       },
       makeTexture: function(gl, img) {
           const tex = gl.createTexture();
           gl.bindTexture(gl.TEXTURE_2D, tex);
           gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
           gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
           gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
           gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
           try {
               if (img) gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
               else gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([246, 248, 246, 255]));
           } catch (e) {}
           return tex;
       },
       initGL: function(canvas, tier) {
           let gl = null;
           try { gl = canvas.getContext('webgl2', { antialias: true, alpha: true }); } catch (e) { return null; }
           if (!gl) return null;
           try {
               const vs = RealFlip.compileShader(gl, gl.VERTEX_SHADER, RealFlip.VERT_SRC);
               const fs = RealFlip.compileShader(gl, gl.FRAGMENT_SHADER, RealFlip.FRAG_SRC);
               if (!vs || !fs) return null;
               const prog = gl.createProgram();
               gl.attachShader(prog, vs);
               gl.attachShader(prog, fs);
               gl.linkProgram(prog);
               if (gl.getProgramParameter && !gl.getProgramParameter(prog, gl.LINK_STATUS)) return null;
               gl.useProgram(prog);
               const cols = tier.cols, rows = tier.rows;
               const n = (cols + 1) * (rows + 1);
               const pos = new Float32Array(n * 3), curl = new Float32Array(n), uv = new Float32Array(n * 2);
               let k = 0;
               for (let j = 0; j <= rows; j++) for (let i = 0; i <= cols; i++) { uv[k * 2] = i / cols; uv[k * 2 + 1] = j / rows; k++; }
               const idx = [];
               for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
                   const a = j * (cols + 1) + i, b = a + 1, c = a + cols + 1, d = c + 1;
                   idx.push(a, c, b, b, c, d);
               }
               const bufPos = gl.createBuffer(), bufUv = gl.createBuffer(), bufCurl = gl.createBuffer(), bufIdx = gl.createBuffer();
               gl.bindBuffer(gl.ARRAY_BUFFER, bufUv);
               gl.bufferData(gl.ARRAY_BUFFER, uv, gl.STATIC_DRAW);
               gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, bufIdx);
               gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx), gl.STATIC_DRAW);
               const ctx = {
                   gl: gl, prog: prog, tier: tier,
                   mesh: { pos: pos, curl: curl, uv: uv, idx: new Uint16Array(idx) },
                   bufPos: bufPos, bufCurl: bufCurl,
                   locPos: gl.getAttribLocation(prog, 'a_pos'),
                   locUv: gl.getAttribLocation(prog, 'a_uv'),
                   locCurl: gl.getAttribLocation(prog, 'a_curl'),
                   uTex: gl.getUniformLocation(prog, 'u_tex'),
                   uBend: gl.getUniformLocation(prog, 'u_bend'),
                   uFoldX: gl.getUniformLocation(prog, 'u_foldX'),
                   uPaper: gl.getUniformLocation(prog, 'u_paper'),
                   texCur: null, texNext: null
               };
               gl.bindBuffer(gl.ARRAY_BUFFER, bufUv);
               gl.enableVertexAttribArray(ctx.locUv);
               gl.vertexAttribPointer(ctx.locUv, 2, gl.FLOAT, false, 0, 0);
               RealFlip.uploadTextures(ctx);
               return ctx;
           } catch (e) { return null; }
       },
       uploadTextures: function(ctx) {
           const st = RealFlip._stage;
           const key = st && st.data ? st.data.key : '';
           const gl = ctx.gl;
           try {
               const curImg = RealFlip._texCache[key + ':cur'] || null;
               const nextImg = RealFlip._texCache[key + ':next'] || null;
               if (!ctx.texCur) ctx.texCur = RealFlip.makeTexture(gl, curImg);
               else if (curImg) { gl.bindTexture(gl.TEXTURE_2D, ctx.texCur); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, curImg); }
               if (!ctx.texNext) ctx.texNext = RealFlip.makeTexture(gl, nextImg);
               else if (nextImg) { gl.bindTexture(gl.TEXTURE_2D, ctx.texNext); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, nextImg); }
           } catch (e) {}
       },
       deformMesh: function(p, dir, grabH) {
           const st = RealFlip._stage;
           if (!st || !st.glCtx) return;
           const cols = st.tier.cols, rows = st.tier.rows;
           const pos = st.glCtx.mesh.pos, curl = st.glCtx.mesh.curl;
           let k = 0, c = 0;
           for (let j = 0; j <= rows; j++) for (let i = 0; i <= cols; i++) {
               const d = RealFlip.deformPoint(i / cols, j / rows, p, dir, grabH);
               pos[k++] = d.x; pos[k++] = d.y; pos[k++] = d.z; curl[c++] = d.curl;
           }
       },
       uploadMesh: function(ctx) {
           const gl = ctx.gl;
           gl.bindBuffer(gl.ARRAY_BUFFER, ctx.bufPos);
           gl.bufferData(gl.ARRAY_BUFFER, ctx.mesh.pos, gl.DYNAMIC_DRAW);
           gl.enableVertexAttribArray(ctx.locPos);
           gl.vertexAttribPointer(ctx.locPos, 3, gl.FLOAT, false, 0, 0);
           gl.bindBuffer(gl.ARRAY_BUFFER, ctx.bufCurl);
           gl.bufferData(gl.ARRAY_BUFFER, ctx.mesh.curl, gl.DYNAMIC_DRAW);
           gl.enableVertexAttribArray(ctx.locCurl);
           gl.vertexAttribPointer(ctx.locCurl, 1, gl.FLOAT, false, 0, 0);
       },
       drawMesh: function(ctx, tex, p, foldX) {
           const gl = ctx.gl;
           gl.useProgram(ctx.prog);
           gl.activeTexture(gl.TEXTURE0);
           gl.bindTexture(gl.TEXTURE_2D, tex);
           gl.uniform1i(ctx.uTex, 0);
           gl.uniform1f(ctx.uBend, RealFlip.curlBend(p));
           gl.uniform1f(ctx.uFoldX, foldX);
           gl.uniform3f(ctx.uPaper, 0.965, 0.973, 0.965);
           gl.drawElements(gl.TRIANGLES, ctx.mesh.idx.length, gl.UNSIGNED_SHORT, 0);
       },
       // 帧率检测：只在动画循环里记（拖动/悬停的零星绘制不记，避免误判）。
       // 连续 5 帧 >50ms → 切 DOM 兜底并记住（perfFallback），返回 true 表示已切换。
       noteFrame: function(now) {
           const st = RealFlip._stage;
           if (!st || st.mode !== 'gl') return false;
           if (st.lastFrameT) {
               const dt = now - st.lastFrameT;
               if (dt > RealFlip.SLOW_DT_MS) st.slowFrames++; else st.slowFrames = 0;
               if (st.slowFrames >= RealFlip.SLOW_FRAMES_MAX) { RealFlip.switchToDom(); return true; }
           }
           st.lastFrameT = now;
           return false;
       },
       switchToDom: function() {
           const st = RealFlip._stage;
           if (!st || st.mode !== 'gl') return;
           RealFlip.perfFallback = true;
           st.mode = 'dom';
           if (st.canvas) st.canvas.style.display = 'none';
           if (st.stageEl) {
               st.stageEl.dataset.realMode = 'dom';
               const note = st.stageEl.querySelector('.ipb-real-note');
               if (note) note.classList.add('ipb-real-show');
           }
           if (RealFlip.onFallback) { const cb = RealFlip.onFallback; try { cb(); } catch (e) {} }
       },
       ensureTextures: function(data) {
           if (!data) return;
           const jobs = [[data.key + ':cur', data.title, data.paras], [data.key + ':next', data.nextTitle, data.nextParas]];
           jobs.forEach(function(job) {
               if (RealFlip._texCache[job[0]]) return;
               RealFlip.rasterizePage(job[1], job[2], data.pageBg || '#f6f8f6', data.ink || '#26313a').then(function(img) {
                   if (img) RealFlip._texCache[job[0]] = img;
                   const st = RealFlip._stage;
                   if (st && st.mode === 'gl' && st.data && st.data.key === data.key && st.glCtx) {
                       RealFlip.uploadTextures(st.glCtx);
                       RealFlip.drawFrame(st.p || 0, 1, 0.5);
                   }
               }).catch(function() {});
           });
       },
       mountStage: function(appWin, data) {
           const bodyDom = appWin.querySelector('#novel-reader-body');
           if (!bodyDom) return null;
           const stageEl = bodyDom.querySelector('.ipb-real-stage');
           if (!stageEl) return null;
           const canvas = stageEl.querySelector('.ipb-real-gl');
           const mobile = RealFlip.isMobileViewport();
           const tier = mobile ? RealFlip.GRID_MOBILE : RealFlip.GRID_DESKTOP;
           const reduced = RealFlip.reducedMotion();
           let glAvailable = false, glCtx = null;
           try { if (canvas && canvas.getContext) glAvailable = !!canvas.getContext('webgl2'); } catch (e) { glAvailable = false; }
           let mode = 'dom';
           if (glAvailable && !reduced && !RealFlip.perfFallback) {
               if (canvas) { canvas.width = 720; canvas.height = 1040; }
               glCtx = RealFlip.initGL(canvas, tier);
               if (glCtx) mode = 'gl';
           }
           if (mode === 'dom' && canvas) canvas.style.display = 'none';
           if (mode === 'gl' && canvas) canvas.style.display = 'block';
           stageEl.dataset.realMode = mode;
           stageEl.dataset.realTier = mobile ? 'mobile' : 'desktop';
           const note = stageEl.querySelector('.ipb-real-note');
           if (note) note.classList.toggle('ipb-real-show', mode === 'dom' && !glAvailable);
           RealFlip._stage = { appWin: appWin, stageEl: stageEl, canvas: canvas, mode: mode, tier: tier, glCtx: glCtx, data: data || {}, drag: null, animating: false, p: 0, grabH: 0.5, peek: false, slowFrames: 0, lastFrameT: 0 };
           if (mode === 'gl') {
               RealFlip.ensureTextures(data);
               RealFlip.drawFrame(0, 1, 0.5);
           }
           return RealFlip._stage;
       },
       // 画一帧：GL 路径画静态叶 + 卷曲叶；DOM 路径摆 rotateY 的叶子
       drawFrame: function(p, dir, grabH) {
           const st = RealFlip._stage;
           if (!st) return false;
           if (st.mode !== 'gl' || !st.glCtx) { RealFlip.applyDomPose(p, dir, grabH); return false; }
           const gl = st.glCtx.gl;
           try {
               const w = st.canvas.width || 720, h = st.canvas.height || 1040;
               gl.viewport(0, 0, w, h);
               gl.clearColor(0, 0, 0, 0);
               gl.clear(gl.COLOR_BUFFER_BIT);
               RealFlip.deformMesh(0, 1, 0.5);
               RealFlip.uploadMesh(st.glCtx);
               RealFlip.drawMesh(st.glCtx, st.glCtx.texCur, 0, 0.5);
               if (p > 0.001) {
                   RealFlip.deformMesh(p, dir, grabH);
                   RealFlip.uploadMesh(st.glCtx);
                   RealFlip.drawMesh(st.glCtx, st.glCtx.texNext, p, (dir > 0) ? (1 - p) : p);
               }
               return true;
           } catch (e) { RealFlip.switchToDom(); return false; }
       },
       applyDomPose: function(p, dir, grabH) {
           const st = RealFlip._stage;
           if (!st || !st.stageEl) return;
           const leaf = st.stageEl.querySelector('.ipb-real-leaf');
           const sh = st.stageEl.querySelector('.ipb-real-shadow');
           if (!leaf) return;
           if (p <= 0.001 && !st.peek) {
               leaf.classList.remove('ipb-real-show');
               leaf.style.transform = '';
               if (sh) sh.style.opacity = '0';
               return;
           }
           leaf.classList.add('ipb-real-show');
           leaf.style.transition = 'none';
           const angle = dir > 0 ? -170 * p : -180 + 180 * p;
           leaf.style.transform = 'perspective(1200px) rotateY(' + angle.toFixed(1) + 'deg)';
           leaf.style.transformOrigin = 'left center';
           if (sh) sh.style.opacity = (0.35 * RealFlip.curlBend(p)).toFixed(2);
       },
       setPeek: function(on) {
           const st = RealFlip._stage;
           if (!st || st.drag || st.animating) return;
           st.peek = !!on;
           if (st.mode === 'gl' && st.glCtx) { RealFlip.drawFrame(on ? 0.06 : 0, 1, 0.5); return; }
           const leaf = st.stageEl && st.stageEl.querySelector('.ipb-real-leaf');
           if (!leaf) return;
           if (on) {
               leaf.classList.add('ipb-real-show');
               leaf.style.transition = 'transform 0.18s ease';
               leaf.style.transform = 'perspective(1200px) rotateY(-12deg)';
           } else {
               leaf.classList.remove('ipb-real-show');
               leaf.style.transform = '';
           }
       },
       _raf: function(fn) {
           if (typeof requestAnimationFrame !== 'undefined') requestAnimationFrame(fn);
           else setTimeout(fn, 16);
       },
       // 通用动画：从当前 p 到 target，Hermite 把释放速度 v0（进度/秒）带进下落
       animateTo: function(target, dir, grabH, v0, onDone) {
           const st = RealFlip._stage;
           if (!st) { if (onDone) onDone(); return; }
           if (RealFlip.reducedMotion() || RealFlip.flipMs <= 0) {
               st.p = 0;
               RealFlip.drawFrame(0, dir, grabH);
               if (onDone) onDone();
               return;
           }
           if (st.animating) return;
           st.animating = true;
           const fromP = st.p || 0;
           const dist = Math.abs(target - fromP);
           if (dist < 0.005) { st.animating = false; st.p = 0; if (onDone) onDone(); return; }
           const dur = Math.max(120, Math.min(RealFlip.flipMs, RealFlip.flipMs * dist));
           const start = Date.now();
           const stepFn = function() {
               const s2 = RealFlip._stage;
               if (!s2 || RealFlip._stage !== st) return;
               if (RealFlip.noteFrame(Date.now())) { s2.animating = false; return; }
               const el = Date.now() - start;
               const p = RealFlip.hermiteRelease(fromP, v0 || 0, target, dur, el);
               const pc = RealFlip.clamp01(p);
               s2.p = pc;
               RealFlip.drawFrame(pc, dir, grabH);
               if (el >= dur) {
                   s2.animating = false;
                   s2.p = 0;
                   RealFlip.drawFrame(0, dir, grabH);
                   const cb = onDone;
                   if (cb) cb();
               } else RealFlip._raf(stepFn);
           };
           RealFlip._raf(stepFn);
       },
       animateFlip: function(dir, grabH, v0, onDone) { RealFlip.animateTo(1, dir, grabH, v0 || 0, onDone); },
       animateToZero: function(dir, grabH, v0, onDone) { RealFlip.animateTo(0, dir, grabH, -Math.abs(v0 || 0), onDone); },
       // 输入：拖页角 / 点左右半边 / 手机滑动 / 键盘方向键 / 桌面悬停页角
       attachInput: function(appWin, isRealMode) {
           const readerDom = appWin.querySelector('#novel-reader-view');
           const bodyDom = appWin.querySelector('#novel-reader-body');
           if (!readerDom || !bodyDom || readerDom.dataset.realBound) return;
           readerDom.dataset.realBound = '1';
           const doc = bodyDom.ownerDocument;
           const win = doc.defaultView || window;
           bodyDom.addEventListener('pointerdown', function(e) {
               const st = RealFlip._stage;
               if (!st || st.animating) return;
               if (!isRealMode()) return;
               if (e.target && e.target.closest && e.target.closest('button, a, input, textarea, select, .ipb-drawer, .ipb-composer')) return;
               try { const sel = win.getSelection(); if (sel && !sel.isCollapsed) return; } catch (err) {}
               const rect = bodyDom.getBoundingClientRect();
               const gh = rect.height ? RealFlip.clamp01((e.clientY - rect.top) / rect.height) : 0.5;
               st.drag = { x0: e.clientX, y0: e.clientY, t0: Date.now(), lastX: e.clientX, lastT: Date.now(), v: 0, dir: 0, p: 0, atEdge: false, grabH: gh };
               try { if (bodyDom.setPointerCapture && e.pointerId !== undefined) bodyDom.setPointerCapture(e.pointerId); } catch (err) {}
           });
           doc.addEventListener('pointermove', function(e) {
               const st = RealFlip._stage;
               if (!st || !st.drag || st.animating) return;
               if (!isRealMode()) { st.drag = null; return; }
               const d = st.drag;
               const now = Date.now();
               const dx = e.clientX - d.x0;
               if (d.dir === 0 && Math.abs(dx) > 6) {
                   d.dir = dx < 0 ? 1 : -1;
                   if (RealFlip.onFlipStart && !RealFlip.onFlipStart(d.dir)) d.atEdge = true;
               }
               if (d.dir !== 0) {
                   const w = bodyDom.clientWidth || 360;
                   let p = RealFlip.clamp01(Math.abs(dx) / w);
                   if (d.atEdge) p = Math.min(p, 0.12);
                   const dt = Math.max(1, now - d.lastT);
                   d.v = (e.clientX - d.lastX) / dt;
                   d.lastX = e.clientX;
                   d.lastT = now;
                   d.p = p;
                   st.p = p;
                   st.grabH = d.grabH;
                   RealFlip.drawFrame(p, d.dir, d.grabH);
               }
           });
           doc.addEventListener('pointerup', function(e) {
               const st = RealFlip._stage;
               if (!st || !st.drag) return;
               const d = st.drag;
               st.drag = null;
               if (!isRealMode() || st.animating) return;
               const dx = e.clientX - d.x0, dy = e.clientY - d.y0, dt = Date.now() - d.t0;
               if (Math.abs(dx) < RealFlip.TAP_PX && Math.abs(dy) < RealFlip.TAP_PX && dt < 500) {
                   const rect = bodyDom.getBoundingClientRect();
                   const w = bodyDom.clientWidth || 360;
                   const x = e.clientX - rect.left;
                   if (RealFlip.onTap) {
                       if (x < w * 0.14) RealFlip.onTap(-1);
                       else if (x > w * 0.86) RealFlip.onTap(1);
                   }
                   return;
               }
               if (d.dir === 0) return;
               const wpx = bodyDom.clientWidth || 360;
               const vProg = Math.min(6, Math.abs(d.v) / wpx * 1000);
               if (!d.atEdge && (d.p > RealFlip.COMMIT_P || Math.abs(d.v) > RealFlip.FLING_V)) {
                   RealFlip.animateFlip(d.dir, d.grabH, vProg, function() { if (RealFlip.onCommit) RealFlip.onCommit(d.dir); });
               } else {
                   RealFlip.animateToZero(d.dir, d.grabH, vProg);
               }
           });
           appWin.addEventListener('keydown', function(e) {
               if (!isRealMode()) return;
               if (e.target && e.target.closest && e.target.closest('input, textarea, select, [contenteditable="true"]')) return;
               const k = e.key;
               if (k === 'ArrowRight' || k === 'ArrowDown' || k === 'PageDown') {
                   if (e.preventDefault) e.preventDefault();
                   if (RealFlip.onTap) RealFlip.onTap(1);
               } else if (k === 'ArrowLeft' || k === 'ArrowUp' || k === 'PageUp') {
                   if (e.preventDefault) e.preventDefault();
                   if (RealFlip.onTap) RealFlip.onTap(-1);
               }
           });
           bodyDom.addEventListener('mousemove', function(e) {
               const st = RealFlip._stage;
               if (!st || st.drag || st.animating) return;
               if (!isRealMode()) return;
               try { if (win.matchMedia && !win.matchMedia('(hover: hover)').matches) return; } catch (err) {}
               const rect = bodyDom.getBoundingClientRect();
               const w = bodyDom.clientWidth || 360, h = bodyDom.clientHeight || 520;
               const x = e.clientX - rect.left, y = e.clientY - rect.top;
               RealFlip.setPeek(x > w - 70 && (y < 90 || y > h - 90));
           });
           bodyDom.addEventListener('mouseleave', function() { RealFlip.setPeek(false); });
       }
   };
   window.RealFlip = RealFlip;


