    const cikeGenerateRaw = async (prompt, feature) => {
        // GROUP-BK: 底层生成口子再兜底一次——prompt 里还没有世界书时，先查世界书（角色未知，只取全局条目，专属条目绝不外泄）再生成。
        try {
            if (typeof window.WorldBook !== 'undefined' && window.WorldBook.firstGlobal && prompt.indexOf('【世界设定') === -1) {
                const _bk = window.WorldBook.firstGlobal('cike', prompt);
                if (_bk.block) prompt = _bk.block + '\n' + prompt;
            }
        } catch (e) {}
        // ① 优先：自建后端
        try {
            if (typeof BackendAPI !== 'undefined' && BackendAPI.isEnabled()) {
                const data = await BackendAPI.cikeGenerate({ prompt });
                if (data && typeof data.text === 'string') return data.text.trim();
            }
        } catch(e) {}
        // ② 兜底：直连 OpenAI 兼容 API
        // [AG组] 接模型 · 日记：配好并打开时先走用户自己的模型（同一 /chat/completions 口子，沿用此刻的日记 system prompt）；失败则记一笔回落，继续走原有链路（自建后端 / GlobalAPI / 微信 apiConfigs），不改变原有行为
        if (feature === 'diary' && typeof window !== 'undefined' && window.PhoneModel && window.PhoneModel.isEnabledFor && window.PhoneModel.isEnabledFor('diary')) {
            try {
                const pmText = await window.PhoneModel.chatComplete([
                    { role: 'system', content: '你是一个深度沉浸式恋爱陪伴AI。完全代入角色，输出真实有温度的内容。不要出现"作为AI"，不要使用括号动作描写。严格按照用户要求的格式输出。' },
                    { role: 'user', content: prompt }
                ], { feature: 'diary' });
                if (pmText) return pmText;
            } catch (e) { /* 已在 chatComplete 里记回落；继续走原有链路 */ }
        }
        const cfg = getApiCfg();
        if (!cfg) throw new Error('NO_API');
        const messages = [
            { role: 'system', content: '你是一个深度沉浸式恋爱陪伴AI。完全代入角色，输出真实有温度的内容。不要出现"作为AI"，不要使用括号动作描写。严格按照用户要求的格式输出。' },
            { role: 'user', content: prompt }
        ];
        const reply = await WeChatAppEngine.callRealAI(cfg, messages, cfg.maxTokens || 500);
        return (reply || '').trim();
    };


