const SULKY = ['宝贝，你终于回我了。', '哼……'];
const sulkyFor = (sess, nowMs) => {
try {
const mem = (sess && sess.memory) || [];
if (mem.length < 2) return '';
let lastUserIdx = -1;
for (let i = mem.length - 1; i >= 0; i--) { if (mem[i].role === 'user') { lastUserIdx = i; break; } }
if (lastUserIdx <= 0) return '';
let lastChar = null;
for (let i = lastUserIdx - 1; i >= 0; i--) { if (mem[i].role !== 'user') { lastChar = mem[i]; break; } }
if (!lastChar || !lastChar.time) return '';
const gap = (nowMs || Date.now()) - lastChar.time;
return gap >= 30 * 60 * 1000 ? SULKY[0] : '';
} catch (e) { return ''; }
};
const burstSegments = (text) => {
const t = String(text || '').trim();
if (!t) return ['……'];
let parts = t.split(/\|\|\||\n/).map(s => s.trim()).filter(Boolean);
let segs = [];
parts.forEach(p => { p.split(/(?<=[。！？；])/).map(s => s.trim()).filter(Boolean).forEach(s => segs.push(s)); });
if (segs.length === 0) segs = [t];
if (segs.length > 3) { const head = segs.slice(0, 2); head.push(segs.slice(2).join(' ')); segs = head; }
if (segs.length === 1 && segs[0].length > 18) {
const s = segs[0];
let cut = Math.floor(s.length / 2);
for (let i = cut; i < s.length; i++) { if ('，、；：'.includes(s[i])) { cut = i + 1; break; } }
if (cut <= 0 || cut >= s.length) cut = Math.floor(s.length / 2);
segs = [s.slice(0, cut).trim(), s.slice(cut).trim()].filter(Boolean);
}
return segs.slice(0, 3);
};
const softenLateNight = (text, hour) => {
const h = (typeof hour === 'number') ? hour : new Date().getHours();
if (h < 23 && h >= 5) return String(text || '');
let first = String(text || '').split(/(?<=[。！？；\n])/)[0].trim() || String(text || '').trim();
if (!first) return '困了……';
if (first.length > 18) { let cut = first.slice(0, 18); const ci = cut.lastIndexOf('，'); if (ci >= 8) cut = cut.slice(0, ci + 1); first = cut; }
if (/困|睡|晚安/.test(first)) return first;
return first + '……困了';
};
