+ '<label style="flex:1;font-size:11px;color:#a08a7a;">天气<input id="ck-k-weather" value="' + esc(day.weather) + '" style="width:100%;box-sizing:border-box;border:1px solid #eadfd4;border-radius:8px;padding:6px;font-size:12px;"></label></div>'
