    return '<div class="tarot-ax-face-art" style="background:linear-gradient(rgba(10,8,32,.55),rgba(10,8,32,.55)),' + card.art + '">'
       + '<svg class="tarot-ax-face-svg" viewBox="0 0 100 150" preserveAspectRatio="none" aria-hidden="true"><rect x="4" y="4" width="92" height="142" fill="none" stroke="rgba(212,175,55,0.9)" stroke-width="1.5"/><rect x="8" y="8" width="84" height="134" fill="none" stroke="rgba(212,175,55,0.45)" stroke-width="0.8"/><circle cx="50" cy="75" r="26" fill="none" stroke="rgba(255,255,255,0.35)" stroke-width="0.8"/></svg>'
       + '<div class="tarot-ax-face-num">' + num + '</div>'
       + '<div class="tarot-ax-face-motif">' + tarotFix1Motif(card) + '</div>'
       + '<div class="tarot-ax-face-name">' + label + '</div>'
