   flipper.className = 'tarot-ax-flipper';
   const back = document.createElement('div');
   back.className = 'tarot-ax-face tarot-ax-face-back';
   back.innerHTML = tarotAxBackHTML();
   const front = document.createElement('div');
   front.className = 'tarot-ax-face tarot-ax-face-front' + (isReversed ? ' tarot-ax-rev' : '');
