 // [GROUP-FIX15] cove-tarot-companion 做法（ISC；只借做法，不抄代码、不抄示例台词与解读文本）：
 //   先征求同意、本机运行；提问→牌阵→抽牌→整组揭示→按需解读；陪伴方接回原文，不另抽一组牌、不自行补造解读；
 //   没有模型也能抽牌，但没有 AI 解读（老实标注）；刷新恢复已保存的牌、正逆位、揭示与原文状态，不重抽、不重请求模型。
 //   本文件是单文件手机，装不下仓库的 Node 服务/本地回环引擎：行为用自己的代码在本地实现；
 //   模型走手机现有的 PhoneModel 设置（设置 → API 设置），不另起一套，不把 key 写进任何新代码。
 const TAROT_CONSENT_KEY = 'tarot_consent_v1'; // 同意记录 {agreed:true, at}，只存本机
 const TAROT_SESSION_KEY = 'tarot_session_v1'; // 当前局完整状态（tarot_history_v1 只存已归档记录，不改它的结构）
 let _tarotSessionSeq = 0; // 会话序号计数器（新一局 +1）
 function tarotAxNewSessionId() { _tarotSessionSeq++; return 'tarot-' + Date.now().toString(36) + '-' + _tarotSessionSeq; }
 function tarotAxHasConsent() {
   try {
     const raw = localStorage.getItem(TAROT_CONSENT_KEY);
     if (raw) { const o = JSON.parse(raw); if (o && o.agreed) return true; }
     // 以前占卜过（有历史记录或有当前局）说明已经用过，不再追问
     const h = JSON.parse(localStorage.getItem('tarot_history_v1') || '[]');
     if (Array.isArray(h) && h.length) return true;
     if (tarotAxLoadSession()) return true;
   } catch (e) {}
   return false;
 }
 function tarotAxSaveConsent() {
   try { localStorage.setItem(TAROT_CONSENT_KEY, JSON.stringify({ agreed: true, at: new Date().toISOString() })); } catch (e) {}
 }
 function tarotAxSessionSnapshot(state) {
   return {
     v: 1,
     sessionId: state.sessionId || '',
     question: (state.question || '').slice(0, 120),
     target: state.target || '自己',
     spreadId: state.spread ? state.spread.id : 'three',
     majorOnly: !!state.majorOnly,
     allowReversed: state.allowReversed !== false,
     drawnCards: (state.drawnCards || []).map((c) => ({ id: c.card ? c.card.id : 0, reversed: !!c.isReversed })),
     // [GROUP-TAROT] 剩余牌堆一起存（只存 id + 正逆位；刷新后补牌用它，不重建整副牌）
     deckPool: (state.deckPool || []).map((e) => ({ id: e.card ? e.card.id : 0, reversed: !!e.reversed })),
     revealedCount: state.revealedCount || 0,
     readingRequested: !!state.readingRequested,
     readingState: state.readingState || 'none',
     readingText: state.readingText || '',
     readingAiText: state.readingAiText || '',
     readingLabel: state.readingLabel || '',
     readingModel: state.readingModel || '',
     fromNight: !!state.fromNight,
     updatedAt: Date.now()
   };
 }
 function tarotAxSaveSession(state) {
   try { localStorage.setItem(TAROT_SESSION_KEY, JSON.stringify(tarotAxSessionSnapshot(state))); } catch (e) {}
 }
 function tarotAxLoadSession() {
   try {
     const raw = localStorage.getItem(TAROT_SESSION_KEY);
     if (!raw) return null;
     const o = JSON.parse(raw);
     if (!o || o.v !== 1 || !Array.isArray(o.drawnCards)) return null;
     if (o.spreadId && !TAROT_AX_SPREADS[o.spreadId]) return null;
     return o;
   } catch (e) { return null; }
 }
 function tarotAxRestoreSession(state) {
   const o = tarotAxLoadSession();
   if (!o) return false;
   state.sessionId = o.sessionId || tarotAxNewSessionId();
   state.question = o.question || '';
   state.target = o.target || '自己';
   state.spread = TAROT_AX_SPREADS[o.spreadId] || TAROT_AX_SPREADS.three;
   state.majorOnly = !!o.majorOnly;
   state.allowReversed = o.allowReversed !== false;
   state.fromNight = !!o.fromNight;
   state.drawnCards = (o.drawnCards || []).map((d) => {
     const card = fullDeck.find((c) => c.id === d.id);
     return card ? { card: card, isReversed: !!d.reversed } : null;
   }).filter(Boolean);
   // [GROUP-TAROT] 剩余牌堆一起恢复：刷新后“再补一张牌”还能用，不会重建整副牌；
   // 旧会话没有该字段（或字段无效）时，按未抽过的牌重建剩余牌堆，补牌不会重复。
   if (Array.isArray(o.deckPool) && o.deckPool.length) {
     const _used = {};
     state.drawnCards.forEach((d) => { if (d.card) _used[d.card.id] = true; });
     state.deckPool = o.deckPool.map((d) => {
       const card = fullDeck.find((c) => c.id === d.id);
       return card ? { card: card, reversed: !!d.reversed } : null;
     }).filter(Boolean).filter((e) => !_used[e.card.id]);
   } else if (state.drawnCards.length) { tarotAxRebuildDeckExcluding(state); }
   state.revealedCount = Math.max(0, Math.min(o.revealedCount || 0, state.drawnCards.length));
   state.readingRequested = !!o.readingRequested;
   // 进行中被刷新打断的解读标 unknown，不自动重发、不重新请求模型
   state.readingState = (o.readingState === 'requesting') ? 'unknown' : (o.readingState || 'none');
   state.readingText = o.readingText || '';
   state.readingAiText = o.readingAiText || '';
   state.readingLabel = o.readingLabel || '';
   state.readingModel = o.readingModel || '';
   state.readingBusy = false;
   if (state.drawnCards.length) { state.currentStep = 'result'; state.axSlotsFlown = true; state.axStage = 'done'; }
   return true;
 }
 // [GROUP-TAROT] 按“未抽过的牌”重建剩余牌堆（历史重开 / 旧会话无剩余牌堆时用）：
 // 只用没抽过的牌；剩余牌堆的正逆位重新抛一次（与已抽的牌无关，不影响已抽牌的正逆位）。
 function tarotAxRebuildDeckExcluding(state) {
   const used = {};
   (state.drawnCards || []).forEach((d) => { if (d.card) used[d.card.id] = true; });
   const src = state.majorOnly ? cardLibrary : fullDeck;
   state.deckPool = src.filter((c) => !used[c.id]).map((c) => ({ card: c, reversed: state.allowReversed === false ? false : tarotAxCoinFlip() }));
   tarotAxFisherYates(state.deckPool);
   return state.deckPool;
 }
 function tarotAxLocalReadingText(reading) {
   if (!reading || !reading.positions || !reading.positions.length) return '';
   const lines = reading.positions.map((p) => p.label + ' — ' + p.card.name + (p.reversed ? ' [逆位]' : ' [正位]') + '：' + (p.meaning || '') + ((p.keywords && p.keywords.length) ? '（关键词：' + p.keywords.join(' · ') + '）' : ''));
   let out = lines.join('\n');
   if (reading.summary) out += '\n整局总结：' + reading.summary;
   if (reading.yesno) out += '\n是/否：' + reading.yesno.answer + '（' + reading.yesno.strength + '）';
   return out;
 }
 // 模型状态与 AI 解读接口（干净接口 + 本地兜底）：只读手机现有的 PhoneModel 配置，
 //   未配/关闭时直接返回未接通，不发任何请求；接通时走 PhoneModel.chatComplete（与微信聊天同一条路）。
 function tarotAxModelStatus() {
   try {
     const pm = window.PhoneModel;
     if (!pm || typeof pm.isConfigured !== 'function' || !pm.isConfigured()) return { connected: false, model: '' };
     let model = '';
     try {
       const cfg = (typeof pm.loadCfg === 'function') ? pm.loadCfg() : null;
       if (cfg && cfg.enabled === false) return { connected: false, model: '' };
       model = (cfg && cfg.model) || '';
     } catch (e) {}
     return { connected: true, model: model };
   } catch (e) { return { connected: false, model: '' }; }
 }
 function tarotAxRequestAiReading(promptText) {
   const pm = window.PhoneModel;
   if (!pm || typeof pm.chatComplete !== 'function') return Promise.reject(new Error('未接模型'));
   return pm.chatComplete([
     { role: 'system', content: '你是塔罗牌的解读助手。用温和、具体的口吻说话，不算命断言，不编造牌面之外的事实。' },
     { role: 'user', content: String(promptText || '').slice(0, 1200) }
   ], { feature: 'tarot', maxTokens: 600 });
 }
 function tarotAxBuildTarotNightPayload(state) {
   const reading = state.lastReading || tarotAxBuildReading(state.drawnCards, state.spread);
   const positions = (reading.positions || []).map((p) => ({ position: p.label, name: p.card ? p.card.name : '', reversed: !!p.reversed, meaning: p.meaning || '', keywords: p.keywords || [] }));
   return {
     sessionId: state.sessionId || '',
     question: (state.question || '').slice(0, 120),
     target: state.target || '自己',
     spreadId: state.spread ? state.spread.id : 'three',
     spreadName: state.spread ? state.spread.name : '',
     fromNight: !!state.fromNight,
     cards: positions,
     readingRequested: !!state.readingRequested,
     readingState: state.readingState || 'none',
     readingLabel: state.readingLabel || '',
     readingText: state.readingRequested ? (state.readingText || '') : '',
     readingAiText: state.readingRequested ? (state.readingAiText || '') : '',
     readingModel: state.readingModel || ''
   };
 }

