   three: { id: 'three', name: '三张牌阵', en: 'Three Cards', count: 3, countLabel: '3张', positions: [{ label: '思想', en: 'Mind', desc: '过去 · 想法' }, { label: '情感', en: 'Heart', desc: '现在 · 感受' }, { label: '行为', en: 'Action', desc: '未来 · 结果' }] },
   five: { id: 'five', name: '五张快抽', en: 'Five Cards', count: 5, countLabel: '5张', positions: [{ label: '过去', en: 'Past', desc: '事情的来处' }, { label: '现在', en: 'Present', desc: '当下的状态' }, { label: '未来', en: 'Future', desc: '可能的发展' }, { label: '建议', en: 'Advice', desc: '可以怎么做' }, { label: '结果', en: 'Outcome', desc: '最可能的结果' }] },
