   sixdir: { id: 'sixdir', name: '六张方向牌阵', en: 'Six Directions', count: 6, countLabel: '6张', positions: [{ label: '东 · 启程', en: 'East · Beginning', desc: '新的开始' }, { label: '南 · 成长', en: 'South · Growth', desc: '正在生长的力量' }, { label: '西 · 收获', en: 'West · Harvest', desc: '将要收获的' }, { label: '北 · 挑战', en: 'North · Challenge', desc: '需要面对的考验' }, { label: '中心 · 内在', en: 'Center · Within', desc: '内心的真实状态' }, { label: '关系 · 伴侣', en: 'Bond · Partner', desc: '与重要之人的关系' }] },
   celtic: { id: 'celtic', name: '凯尔特十字', en: 'Celtic Cross', count: 10, countLabel: '10张', positions: [{ label: '现状', en: 'Present', desc: '眼下的局面' }, { label: '交叉', en: 'Crossing', desc: '横在面前的挑战（横放）' }, { label: '根基', en: 'Foundation', desc: '事情的根源' }, { label: '过去', en: 'Past', desc: '刚刚过去的影响' }, { label: '可能', en: 'Potential', desc: '可能的发展' }, { label: '未来', en: 'Future', desc: '近期的走向' }, { label: '自我', en: 'Self', desc: '你自己的状态' }, { label: '环境', en: 'Environment', desc: '周围的人与事' }, { label: '希望', en: 'Hopes', desc: '心里的期待与害怕' }, { label: '结果', en: 'Outcome', desc: '最终的落点' }] },
   tree: { id: 'tree', name: '生命之树', en: 'Tree of Life', count: 10, countLabel: '10张', positions: [{ label: '王冠', en: 'Kether · Crown', desc: '最高的指引' }, { label: '智慧', en: 'Chokmah · Wisdom', desc: '主动的力量' }, { label: '理解', en: 'Binah · Understanding', desc: '接纳与孕育' }, { label: '仁慈', en: 'Chesed · Mercy', desc: '给予与扩张' }, { label: '严厉', en: 'Geburah · Severity', desc: '界限与取舍' }, { label: '美丽', en: 'Tiphareth · Beauty', desc: '内心的平衡点' }, { label: '胜利', en: 'Netzach · Victory', desc: '渴望与坚持' }, { label: '光辉', en: 'Hod · Splendor', desc: '思考与表达' }, { label: '基础', en: 'Yesod · Foundation', desc: '潜意识的地基' }, { label: '王国', en: 'Malkuth · Kingdom', desc: '落到现实的结果' }] },
