 const fullDeck = [...cardLibrary];
 const suits = ['权杖', '圣杯', '宝剑', '星币'];
 const ranks = ['王牌', '二', '三', '四', '五', '六', '七', '八', '九', '十', '侍从', '骑士', '王后', '国王'];
 let currentId = 25;
 suits.forEach(suit => {
   ranks.forEach(rank => {
     fullDeck.push({
       id: currentId++,
       name: `${suit}${rank}`,
       type: '小阿卡纳',
       art: tarotAxMinorArt(suit, ranks.indexOf(rank)),
       symbol: suit === '权杖'?'🔥':suit === '圣杯'?'🍷':suit === '宝剑'?'⚔️':'🪙',
       desc: `代表着在${suit}领域中关于${rank}特质的关键演变与运势推演。`
     });
   });
 });

