   // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   // 3. 细粒度调度中枢 (执行绝对沙盒内DOM结构重绘与全域状态广播)
   // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   const Controller = {
       updateConsoleLog: (text, appWin) => {
           const screenText = appWin.querySelector('#nb-screen-log');
           if (screenText) screenText.innerText = text;
           // 每次学习动作后顺带持久化统计（学习/拼写/考场渲染都会走这里）
           try { localStorage.setItem('nobeidanci_stats_v1', JSON.stringify(Store.stats)); } catch(e){}
       },

       // 全域同步广播核心函数：操纵分布在主页、考场及伴读舱内的所有图片映射层
       broadcastPetSyncState: (appWin) => {
           const syncImagesPool = appWin.querySelectorAll('.nb-sync-pet-img');
           syncImagesPool.forEach(imgDom => {
               if (Store.partnerImg) {
                   imgDom.src = Store.partnerImg;
                   imgDom.style.display = 'block';
               } else {
                   imgDom.style.display = 'none';
               }
           });
       },

       // 步骤一：推入书架大厅层
       renderBookshelfHall: (appWin) => {
           const space = appWin.querySelector('#nb-bookshelf-sub-space');
           if (!space) return;
           space.innerHTML = `
               <div class="nb-bookshelf-grid">
                   <div class="nb-book-item" id="nb-target-core-book">
                       <div class="nb-book-name">入门 5 词<br>可导入扩充</div>
                       <div style="color:rgba(255,255,255,0.6);font-size:11px;font-family:monospace;">内置 ${Store.vocabulary.length} 词 · 静态例句</div>
                   </div>
                   <div class="nb-book-item" data-action-target="import-book" style="background:linear-gradient(135deg, #ffffff, #fffdf8);border-left-color:#bfc8e0;box-shadow:0 2px 6px rgba(30,39,72,.06), 0 4px 12px rgba(30,39,72,.04);border:1px solid #eef0f5;cursor:pointer;">
                       <div class="nb-book-name" style="color:#1e2748;">+<br>扩展载入词库</div>
                       <div style="color:#46536f;font-size:11px;font-family:monospace;">外部挂载通道</div>
                   </div>
               </div>
           `;
           Controller.updateConsoleLog("BOOKSHELF LOADED", appWin);

           const bookBtn = space.querySelector('#nb-target-core-book');
           if (bookBtn) bookBtn.onclick = () => Controller.renderBookDetailView(appWin);
       },

       // 步骤二：推入书籍概览详情页 (精绘纯CSS/SVG极简现代图书Icon，彻底取代Emoji)
       renderBookDetailView: (appWin) => {
           const space = appWin.querySelector('#nb-bookshelf-sub-space');
           if (!space) return;
           const mastered = Store.stats.myWords;
           const total = Store.vocabulary.length;
           // 口径统一：以词库总量为准，已掌握不超出总量，剩余 = 总量 - 已掌握（修复前 72 掌握 / 5 剩余 / 88% 三数互斥）
           const masteredInPool = Math.min(mastered, total);
           const remaining = total - masteredInPool;
           const pct = total ? Math.round((masteredInPool / total) * 100) : 0;

           space.innerHTML = `
               <div style="background:#ffffff;border-radius:22px;box-shadow:0 2px 6px rgba(30,39,72,.06), 0 8px 20px rgba(30,39,72,.05);border:1px solid rgba(30,39,72,0.08);overflow:hidden;animation:nbFadeIn 0.25s ease;">
                   <div style="padding:24px;background:#fffdf8;border-bottom:1px solid #eef0f5;display:flex;justify-content:space-between;align-items:center;">
                       <div>
                           <div style="font-size:18px;font-weight:900;color:#1e2748;">入门 5 词</div>
                           <div style="font-size:11px;color:#46536f;margin-top:4px;font-weight:bold;">内置 5 词 · 可导入扩充</div>
                       </div>
                       <div style="width:46px;height:46px;border-radius:14px;background:#dce2f1;display:flex;align-items:center;justify-content:center;border:1px solid rgba(30,39,72,0.16);">
                           <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#171717" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                               <path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H12v18H6.5A2.5 2.5 0 0 1 4 19.5Z"></path>
                               <path d="M20 19.5v-15A2.5 2.5 0 0 0 17.5 2H12v18h5.5a2.5 2.5 0 0 0 2.5-2.5Z"></path>
                           </svg>
                       </div>
                   </div>
                   <div style="padding:24px;">
                       <div style="display:flex;justify-content:space-between;font-size:12px;color:#46536f;font-weight:bold;margin-bottom:8px;">
                           <span>学习渗透率</span>
                           <span style="color:#1e2748;font-family:monospace;">${pct}%</span>
                       </div>
                       <div style="width:100%;height:6px;background:#eef0f5;border-radius:3px;overflow:hidden;margin-bottom:20px;">
                           <div style="width:${pct}%;height:100%;background:#1e2748;border-radius:3px;transition:width 0.5s;"></div>
                       </div>
                       <div style="display:flex;justify-content:space-between;font-size:13px;color:#1e2748;margin-bottom:24px;padding:10px 14px;background:#fffdf8;border-radius:12px;">
                           <span>已掌握: <strong>${masteredInPool}</strong> 词</span>
                           <span>剩余攻坚: <strong>${remaining}</strong> 词</span>
                       </div>
                       <button class="nb-btn-base" style="background:#1e2748;height:46px;font-size:14px;" id="nb-execute-learn-btn">立即进入沉浸背单词 <svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></button>
                   </div>
               </div>
               <div style="text-align:center;margin-top:20px;">
                   <span style="font-size:13px;color:#a9b3cc;cursor:pointer;font-weight:bold;" id="nb-back-hall-btn"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H5m6-6-6 6 6 6"/></svg> 退回大厅书架矩阵</span>
               </div>
           `;
           Controller.updateConsoleLog("BOOK DETAIL READY", appWin);

           const startBtn = space.querySelector('#nb-execute-learn-btn');
           const backBtn = space.querySelector('#nb-back-hall-btn');
           if (startBtn) startBtn.onclick = () => Controller.renderBookTestScreen(appWin);
           if (backBtn) backBtn.onclick = () => Controller.renderBookshelfHall(appWin);
       },

       // 步骤三：真正进入沉浸式背单词域 (图1/图2落地短文态)
       renderBookTestScreen: (appWin) => {
           const wordObj = Store.vocabulary[Store.cardIndex % Store.vocabulary.length];
           const spaceWrap = appWin.querySelector('#nb-bookshelf-sub-space');
           if (!spaceWrap || !wordObj) return;

           spaceWrap.innerHTML = `
               <div class="nb-green-screen">
                   <div class="nb-word-header">
                       <div class="nb-word-text">
                           <span>${wordObj.en}</span>
                           <span style="font-size:18px;color:#46536f;">⋮</span>
                       </div>
                       <div class="nb-word-phonetic-box">
                           <span class="nb-sound-pill">英</span>
                           <span class="nb-phonetic-text">${wordObj.phonetic}</span>
                       </div>
                       <div class="nb-hint-tip">先回想词义再选择，想不起来「看答案」</div>
                       
                       <div class="nb-test-options-wrap" id="nb-test-opt-group">
                           ${wordObj.options.map((opt, idx) => `
                               <div class="nb-opt-card" data-opt-idx="${idx}">${opt}</div>
                           `).join('')}
                       </div>
                   </div>

                   <div class="nb-show-ans-trigger" id="nb-trigger-ans-btn">
                       <span class="nb-ans-text">看答案</span>
                       <div class="nb-ans-line"></div>
                   </div>

                   <div class="nb-answer-view-wrap" id="nb-ans-full-view">
                       <div class="nb-ans-def-line">${wordObj.zh}</div>
                       
                       <div class="nb-memory-card">
                           <div style="position:absolute;bottom:6px;right:10px;font-size:12px;color:#bfc8e0;"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.5h8l4 4V20H6Z"/><path d="M14 3.5v4h4M9 12h6m-6 3h6"/></svg></div>
                           <div class="nb-memory-text">${Controller.parseMarkdown(wordObj.memoryContext)}</div>
                           <div style="font-size:10px;color:#a9b3cc;margin-top:8px;text-align:right;">内置例句 · 静态短文</div>
                       </div>

                       <div class="nb-collocation-card">
                           <div class="nb-collocation-title">${wordObj.en.split(' ')[0]} 专属高频词组</div>
                           <div style="font-size:13px;color:#1e2748;font-weight:700;margin-top:2px;">${wordObj.collocation}</div>
                       </div>

                       <div class="nb-next-pill-wrap" id="nb-next-word-btn">
                           <span class="nb-next-text">下一词</span>
                           <div class="nb-next-line"></div>
                       </div>
                   </div>
               </div>
           `;

           Controller.updateConsoleLog(`TESTING: ${wordObj.en.toUpperCase()}`, appWin);

           const optCards = spaceWrap.querySelectorAll('.nb-opt-card');
           const ansBtn = spaceWrap.querySelector('#nb-trigger-ans-btn');
           const ansView = spaceWrap.querySelector('#nb-ans-full-view');
           const optGroup = spaceWrap.querySelector('#nb-test-opt-group');
           const nextBtn = spaceWrap.querySelector('#nb-next-word-btn');

           const showAnswerLogic = (isCorrect = false) => {
               if (optGroup) optGroup.style.display = 'none';
               if (ansBtn) ansBtn.style.display = 'none';
               if (ansView) ansView.style.display = 'flex';
               if (isCorrect) Store.stats.myWords += 1;
               else Store.stats.reviewNum += 1;
           };

           optCards.forEach(card => {
               card.onclick = () => {
                   const selIdx = parseInt(card.getAttribute('data-opt-idx'));
                   if (selIdx === wordObj.correctIndex) {
                       showAnswerLogic(true);
                   } else {
                       card.style.borderColor = '#e53e3e'; card.style.color = '#e53e3e';
                       setTimeout(() => showAnswerLogic(false), 200);
                   }
               };
           });
           if (ansBtn) ansBtn.onclick = () => showAnswerLogic(false);
           if (nextBtn) {
               nextBtn.onclick = () => { Store.cardIndex += 1; Controller.renderBookTestScreen(appWin); };
           }
       },

       // 独立分发渲染图3：紫罗兰全景大卡片 (绝对删除中央三角形播放标记，纯净释放)
       renderVioletLearnSpace: (appWin) => {
           const wordObj = Store.vocabulary[Store.cardIndex % Store.vocabulary.length];
           const learnWrap = appWin.querySelector('#nb-violet-space-wrap');
           if (!learnWrap || !wordObj) return;

           learnWrap.innerHTML = `
               <div class="nb-violet-card">
                   <div class="nb-vc-header">
                       <span class="nb-vc-tag">词库 · 入门 5 词</span>
                       <div class="nb-vc-tools">
                           <div class="nb-vc-tool-btn" id="nb-tool-heart"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 8.8c0 5-8.5 10.2-8.5 10.2S3.5 13.8 3.5 8.8c0-3.6 4.5-4.9 8.5-.8 4-4.1 8.5-2.8 8.5.8Z"/></svg></div>
                           <div class="nb-vc-tool-btn" id="nb-tool-hint" title="提示释义前两字"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 16c0-2-3-3.2-3-7a7 7 0 0 1 14 0c0 3.8-3 5-3 7Zm1 2h6m-5 3h4"/></svg></div>
                       </div>
                   </div>

                   <div class="nb-vc-center">
                       <div class="nb-vc-word">${wordObj.en}</div>
                       <div class="nb-vc-phonetic">${wordObj.phonetic}</div>
                   </div>

                   <div class="nb-vc-footer">
                       <div class="nb-vc-progress">
                           <span>${(Store.cardIndex % Store.vocabulary.length) + 1}</span>
                           <span style="font-size:8px;border-top:1px solid rgba(255,255,255,0.4);width:60%;text-align:center;margin-top:1px;">${Store.vocabulary.length}</span>
                       </div>
                       <div class="nb-vc-actions">
                           <div class="nb-vc-btn" id="nb-vc-reveal-btn">查看释义</div>
                           <div class="nb-vc-btn" style="background:#fffdf8;color:#1e2748;" id="nb-vc-pass-btn">掌握直接过</div>
                       </div>
                   </div>
               </div>

               <div class="nb-back-content" id="nb-bc-card">
                   <div class="nb-bc-def">${wordObj.zh}</div>
                   <div class="nb-bc-memory">${Controller.parseMarkdown(wordObj.memoryContext)}</div>
                   <div style="margin-top:12px;font-size:12px;color:#46536f;display:flex;justify-content:space-between;align-items:center;">
                       <span>例句 · 静态短文</span>
                       <button class="nb-btn-base" style="width:auto;padding:6px 14px;background:#1e2748;font-size:11px;" id="nb-bc-next-btn">下一词</button>
                   </div>
               </div>
           `;
           Controller.updateConsoleLog(`SYNC: ${wordObj.en.toUpperCase()}`, appWin);

           const revealBtn = learnWrap.querySelector('#nb-vc-reveal-btn');
           const passBtn = learnWrap.querySelector('#nb-vc-pass-btn');
           const nextBtn = learnWrap.querySelector('#nb-bc-next-btn');
           const bcCard = learnWrap.querySelector('#nb-bc-card');
           const heartBtn = learnWrap.querySelector('#nb-tool-heart');

           if (heartBtn) heartBtn.onclick = () => { heartBtn.innerHTML = '<svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 8.8c0 5-8.5 10.2-8.5 10.2S3.5 13.8 3.5 8.8c0-3.6 4.5-4.9 8.5-.8 4-4.1 8.5-2.8 8.5.8Z" fill="currentColor" stroke="none"/></svg>'; };
           const showBack = () => { if (bcCard) bcCard.style.display = 'block'; const d = learnWrap.querySelector('.nb-bc-def'); if (d) d.innerText = wordObj.zh; if (revealBtn) revealBtn.style.display = 'none'; };
           // 💡 提示：只露出释义前两字，不直接揭晓全文（修复前只弹一句“同步就绪”）
           const hintBtn = learnWrap.querySelector('#nb-tool-hint');
           if (hintBtn) hintBtn.onclick = () => {
               const defEl = learnWrap.querySelector('.nb-bc-def');
               if (defEl && bcCard) { defEl.innerText = (wordObj.zh || '').slice(0, 2) + '……'; bcCard.style.display = 'block'; }
           };
           if (revealBtn) revealBtn.onclick = () => { Store.stats.reviewNum += 1; showBack(); };
           if (passBtn) passBtn.onclick = () => { Store.stats.myWords += 1; Store.cardIndex += 1; Controller.renderVioletLearnSpace(appWin); };
           if (nextBtn) nextBtn.onclick = () => { Store.cardIndex += 1; Controller.renderVioletLearnSpace(appWin); };
       },

       parseMarkdown: (str) => {
           return str.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
       },

       renderSpellScreen: (appWin) => {
           const item = Store.vocabulary[Math.floor(Math.random() * Store.vocabulary.length)];
           Store.spellTarget = item;
           const spaceWrap = appWin.querySelector('#nb-spell-space-wrap');
           if (!spaceWrap) return;

           spaceWrap.innerHTML = `
               <div class="nb-spell-screen">
                   <div class="nb-spell-top-capsule">
                       <div class="nb-cap-btn" id="nb-spell-clear-btn"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5h11a1.5 1.5 0 0 1 1.5 1.5v11A1.5 1.5 0 0 1 20 19H9l-6.5-7Z"/><path d="m12 10 4 4m0-4-4 4"/></svg></div>
                       <div class="nb-cap-confirm" id="nb-spell-confirm-btn">确认</div>
                       <div class="nb-cap-btn" id="nb-spell-hint-btn" title="提示首字母"><svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 16c0-2-3-3.2-3-7a7 7 0 0 1 14 0c0 3.8-3 5-3 7Zm1 2h6m-5 3h4"/></svg></div>
                   </div>

                   <div class="nb-spell-center-zone">
                       <div class="nb-spell-input-box">
                           <input type="text" class="nb-spell-input-real" id="nb-spell-input-dom" autocomplete="off" spellcheck="false" />
                           <div class="nb-spell-cursor"></div>
                       </div>
                       <div class="nb-spell-zh-hint">${item.zh.split('；')[0]}</div>
                   </div>
               </div>
           `;
           Controller.updateConsoleLog("SPELL STANDBY", appWin);

           const inpDom = spaceWrap.querySelector('#nb-spell-input-dom');
           const confirmBtn = spaceWrap.querySelector('#nb-spell-confirm-btn');
           const clearBtn = spaceWrap.querySelector('#nb-spell-clear-btn');

           if (inpDom) { setTimeout(() => inpDom.focus(), 100); }
           if (clearBtn && inpDom) clearBtn.onclick = () => { inpDom.value = ''; inpDom.focus(); };
           // 💡 提示：填入当前单词首字母（修复前只弹一句通用提示）
           const hintBtn = spaceWrap.querySelector('#nb-spell-hint-btn');
           if (hintBtn && inpDom) hintBtn.onclick = () => { if (Store.spellTarget && !inpDom.value) { inpDom.value = Store.spellTarget.en.charAt(0); inpDom.focus(); } };
           if (confirmBtn) confirmBtn.onclick = () => Controller.verifySpellLogic(appWin);
           // 拼写页标题显示当前单词（修复前固定写死 resemble）
           const spellTitle = appWin.querySelector('#nb-view-spell .nb-sub-title');
           if (spellTitle && Store.spellTarget) spellTitle.textContent = Store.spellTarget.en;
       },

       verifySpellLogic: (appWin) => {
           const inp = appWin.querySelector('#nb-spell-input-dom');
           const hintDom = appWin.querySelector('.nb-spell-zh-hint');
           if (!inp || !hintDom || !Store.spellTarget) return;
           if (inp.value.trim().toLowerCase() === Store.spellTarget.en.toLowerCase()) {
               hintDom.style.color = '#38a169'; hintDom.innerText = '拼写校验完美通过！';
               Store.stats.myWords += 1; Controller.updateConsoleLog("SPELL CORRECT", appWin);
               setTimeout(() => Controller.renderSpellScreen(appWin), 700);
           } else {
               hintDom.style.color = '#e53e3e'; hintDom.innerText = `正确拼写为: ${Store.spellTarget.en}`; Controller.updateConsoleLog("SPELL ERROR", appWin);
               setTimeout(() => { hintDom.style.color = '#46536f'; hintDom.innerText = `vt. ${Store.spellTarget.zh.split('；')[0]}`; }, 1600);
           }
       },

       renderAiExamScreen: (appWin) => {
           const item = Store.vocabulary[Math.floor(Math.random() * Store.vocabulary.length)];
           const wrap = appWin.querySelector('#nb-exam-options-wrap');
           const bubble = appWin.querySelector('#nb-exam-pet-bubble');
           if (!wrap) return;

           const isCollocation = Math.random() > 0.5;
           let questionText = "";
           if (isCollocation) {
               questionText = `“宝宝请听题，在词组搭配【${item.collocation.replace(item.en, '___')}】中，空缺处应填入哪个词？”`;
           } else {
               questionText = `“现场提问：短文场景中表示【${item.zh.split('；')[0]}】的核心词汇是哪个？”`;
           }
           if (bubble) bubble.innerText = questionText;

           let opts = [item.en];
           while (opts.length < 3) {
               const randItem = Store.vocabulary[Math.floor(Math.random() * Store.vocabulary.length)];
               if (!opts.includes(randItem.en)) opts.push(randItem.en);
           }
           opts.sort(() => Math.random() - 0.5);

           wrap.innerHTML = opts.map(o => `
               <div style="background:#fffdf8;padding:14px 18px;border-radius:14px;font-size:14px;color:#1e2748;cursor:pointer;border:1px solid #eef0f5;text-align:center;font-weight:900;font-family:monospace;" data-exam-opt="${o}">${o}</div>
           `).join('');
           Controller.updateConsoleLog("AI QUESTIONING...", appWin);
           
           // 确保每次动态刷新考卷时，出题考官核心的图片覆盖层严格保持同步
           Controller.broadcastPetSyncState(appWin);

           wrap.querySelectorAll('[data-exam-opt]').forEach(dom => {
               dom.onclick = () => {
                   if (dom.getAttribute('data-exam-opt') === item.en) {
                       Store.stats.myWords += 1; if (bubble) bubble.innerText = "“完全正确！这个词记住了。”";
                       Controller.updateConsoleLog("EXAM HIT", appWin); setTimeout(() => Controller.renderAiExamScreen(appWin), 800);
                   } else {
                       Store.stats.reviewNum += 1; if (bubble) bubble.innerText = `“哎呀偏差了，应该是大写核心词「${item.en}」哦！”`;
                       Controller.updateConsoleLog("EXAM MISS", appWin); setTimeout(() => Controller.renderAiExamScreen(appWin), 1500);
                   }
               };
           });
       },

       setupPartnerSystem: (appWin) => {
           const streamDom = appWin.querySelector('#nb-pet-msg-stream');
           Controller.broadcastPetSyncState(appWin); // 瞬间分发更新全域立绘节点

           const triggerStream = () => {
               if (!streamDom) return;
               const pool = ["内置例句 · 静态短文", "伴读舱运行中", "点一点桌宠，和 TA 打个招呼", "今天也要一起背单词"];
               streamDom.innerText = pool[Math.floor(Math.random() * pool.length)];
               streamDom.classList.remove('pop'); void streamDom.offsetWidth; streamDom.classList.add('pop');
               setTimeout(() => streamDom.classList.remove('pop'), 2400);
           };

           if (Store.partnerInterval) clearInterval(Store.partnerInterval);
           Store.partnerInterval = setInterval(() => {
               const view = appWin.querySelector('#nb-view-partner');
               if (view && view.classList.contains('show')) { if (Math.random() > 0.3) triggerStream(); }
           }, 5000);

           const avatarBox = appWin.querySelector('#nb-pet-interactive-zone');
           if (avatarBox) avatarBox.onclick = triggerStream;
           Controller.updateConsoleLog("PARTNER ACTIVE", appWin);
       },

       toggleRecordPaper: (appWin) => {
           const paperDom = appWin.querySelector('#nb-paper-record-layer');
           if (!paperDom) return;
           const isOpened = paperDom.classList.contains('active');
           if (!isOpened) {
               // 只展示真实统计，不再每次点开纸条就凭空 +2/+4/+3/+8
               appWin.querySelector('#nb-stat-my-time').innerText = Store.stats.myTime;
               appWin.querySelector('#nb-stat-my-words').innerText = Store.stats.myWords;
               appWin.querySelector('#nb-stat-my-rev').innerText = Store.stats.reviewNum;
               appWin.querySelector('#nb-stat-ai-time').innerText = Store.stats.aiTime;
               appWin.querySelector('#nb-stat-ai-words').innerText = Store.stats.aiWords;
               // AI 侧无真实活动时显示“还没有伴读记录”，有活动时隐藏
               const _aiEmpty = appWin.querySelector('#nb-ai-empty');
               if (_aiEmpty) _aiEmpty.style.display = (Store.stats.aiTime > 0 || Store.stats.aiWords > 0) ? 'none' : '';
               paperDom.classList.add('active'); Controller.updateConsoleLog("PAPER SLID OUT", appWin);
           } else {
               paperDom.classList.remove('active'); Controller.updateConsoleLog("PAPER RETRACTED", appWin);
           }
       },

       openView: (viewId, appWin) => {
           const paperDom = appWin.querySelector('#nb-paper-record-layer');
           if (paperDom) paperDom.classList.remove('active');

           const targetView = appWin.querySelector('#nb-view-' + viewId);
           if (targetView) targetView.classList.add('show');

           if (viewId === 'bookshelf') Controller.renderBookshelfHall(appWin);
           if (viewId === 'learn') Controller.renderVioletLearnSpace(appWin);
           if (viewId === 'spell') Controller.renderSpellScreen(appWin);
           if (viewId === 'exam') Controller.renderAiExamScreen(appWin);
           if (viewId === 'partner') Controller.setupPartnerSystem(appWin);
           
           // 路由推入时自动校验一遍全域立绘同步锁
           Controller.broadcastPetSyncState(appWin);
       },

       closeView: (viewId, appWin) => {
           const targetView = appWin.querySelector('#nb-view-' + viewId);
           if (targetView) targetView.classList.remove('show');
           if (viewId === 'partner' && Store.partnerInterval) clearInterval(Store.partnerInterval);
           Controller.updateConsoleLog("OS STANDBY", appWin);
       }
   };

