// ══════════════════════════════════════════════════════════════════════
// VisionAPI · 视觉模型 API 调用模块 v1.0
// 与 GlobalAPI（聊天）、MiniMax（TTS）完全独立，三者可并行调用
// 使用 OpenAI 兼容的 chat/completions 多模态格式，适配
// 智谱 GLM-4V、阿里 Qwen-VL、字节豆包视觉、Kimi 视觉、Step-1V、GPT-4o、Gemini 等
// ══════════════════════════════════════════════════════════════════════
const VisionAPI = (() => {
    const KEY = 'phone_vision_cfg';

    const getConfig = () => {
        try { return JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch(e) { return {}; }
    };
    const isConfigured = () => {
        const c = getConfig();
        return !!(c.apiKey && c.baseUrl && c.model);
    };

    // 把 baseUrl 规范成 chat/completions endpoint
    const buildEndpoint = (baseUrl) => {
        let url = (baseUrl || '').replace(/\/+$/, '');
        if (/\/chat\/completions$/.test(url)) return url;
        // 若 url 已有 /vN 或带平台前缀（/paas、/compatible-mode、/openai 等）就直接拼 /chat/completions
        if (/\/v\d+$/.test(url) || /\/(paas|compatible-mode|openai|api\/v\d+)/.test(url)) {
            return url + '/chat/completions';
        }
        return url + '/v1/chat/completions';
    };

    // 主调用方法
    // opts: { imageUrl?, imageBase64?, mimeType?, prompt?, maxTokens?, history? }
    //   - imageUrl: 可访问的图片 URL（http(s)://）
    //   - imageBase64: 纯 base64 串或 "data:image/...;base64,..." data-URL
    //   - prompt: 提问文本（默认"请描述图片内容"）
    //   - history: [{role, content}] 可选历史，会插在视觉消息前面
    const analyzeImage = async (opts = {}) => {
        const cfg = getConfig();
        if (!cfg.apiKey || !cfg.baseUrl || !cfg.model) {
            throw new Error('视觉模型 API 尚未配置（设置 → 克隆音色 → 视觉模型 API 配置）');
        }
        const prompt = opts.prompt || '请描述这张图片的内容，简明扼要。';
        const maxTokens = Number(opts.maxTokens) || 800;

        // 构造图片 URL（API 端的 image_url 字段既支持 http(s) URL 也支持 data: URL）
        let imgUrl;
        if (opts.imageUrl) {
            imgUrl = opts.imageUrl;
        } else if (opts.imageBase64) {
            const mime = opts.mimeType || 'image/jpeg';
            imgUrl = opts.imageBase64.startsWith('data:')
                ? opts.imageBase64
                : `data:${mime};base64,${opts.imageBase64}`;
        } else {
            throw new Error('analyzeImage 需要 imageUrl 或 imageBase64');
        }

        const userMsg = {
            role: 'user',
            content: [
                { type: 'text', text: prompt },
                { type: 'image_url', image_url: { url: imgUrl } }
            ]
        };
        const messages = Array.isArray(opts.history) && opts.history.length
            ? [...opts.history, userMsg]
            : [userMsg];

        const endpoint = buildEndpoint(cfg.baseUrl);
        const body = {
            model: cfg.model,
            messages: messages,
            max_tokens: maxTokens
        };

        const resp = await fetch(endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + cfg.apiKey
            },
            body: JSON.stringify(body)
        });
        if (!resp.ok) {
            const text = await resp.text().catch(() => '');
            throw new Error('视觉 API HTTP ' + resp.status + ' ' + text.slice(0, 200));
        }
        const data = await resp.json();
        const reply = data?.choices?.[0]?.message?.content;
        if (reply === undefined || reply === null) throw new Error('视觉 API 返回格式异常');

        // 上报 Token 消耗（与 GlobalAPI 一致的统计口径）
        if (typeof window.reportTokenUsage === 'function') {
            let used = data?.usage?.total_tokens;
            if (!used) used = Math.round((prompt.length + String(reply).length) / 1.5);
            try { window.reportTokenUsage('视觉模型', used, 1); } catch(e){}
        }
        return String(reply).trim();
    };

    // 并行调用三套 API 的便捷方法（聊天 + 语音 + 视觉同时跑）
// payload: { chat?: {messages, maxTokens}, tts?: {text, voiceId}, vision?: {imageUrl|imageBase64, prompt} }
    // 返回: { chat, tts, vision } 三个 Promise 的并行结果（失败的字段为 {error}）
    const callAllParallel = async (payload = {}) => {
        const tasks = {};

        // 1) 聊天 API（走 GlobalAPI / WeChatAppEngine.callRealAI）
        if (payload.chat) {
            tasks.chat = (async () => {
                if (window.GlobalAPI && window.GlobalAPI.isConfigured()) {
                    const cfg = window.GlobalAPI.getConfig();
                    if (window.WeChatAppEngine?.callRealAI) {
                        return window.WeChatAppEngine.callRealAI(
                            { baseUrl: cfg.baseUrl, key: cfg.key, model: cfg.model, temperature: cfg.temperature, maxTokens: cfg.maxTokens },
                            payload.chat.messages || [],
                            payload.chat.maxTokens
                        );
                    }
                }
                throw new Error('聊天 API 未配置');
            })().catch(err => ({ error: err.message }));
        }

        // 2) 语音 API（MiniMax T2A）
        if (payload.tts) {
            tasks.tts = (async () => {
                let mm = {};
                try { mm = JSON.parse(localStorage.getItem('phone_minimax_cfg') || '{}'); } catch(e){}
                if (!mm.groupId || !mm.apiKey) throw new Error('MiniMax 未配置');
                const r = await fetch(`https://api.minimax.chat/v1/t2a_v2?GroupId=${mm.groupId}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + mm.apiKey },
                    body: JSON.stringify({
                        model: 'speech-01-turbo',
                        text: payload.tts.text || '',
                        stream: false,
                        voice_setting: { voice_id: payload.tts.voiceId || 'female-tianmei', speed: 1.0, vol: 1.0, pitch: 0 }
                    })
                });
                const d = await r.json();
                if (d.base_resp?.status_code !== 0 && !d.audio_file && !d.data?.audio) {
                    throw new Error(d.base_resp?.status_msg || 'TTS 失败');
                }
                return d.audio_file || d.data?.audio;
            })().catch(err => ({ error: err.message }));
        }

        // 3) 视觉 API
        if (payload.vision) {
            tasks.vision = analyzeImage(payload.vision).catch(err => ({ error: err.message }));
        }

        // 三路并行 await
        const keys = Object.keys(tasks);
        const results = await Promise.all(keys.map(k => tasks[k]));
        const out = {};
        keys.forEach((k, i) => { out[k] = results[i]; });
        return out;
    };
    return { getConfig, isConfigured, analyzeImage, callAllParallel };
})();
window.VisionAPI = VisionAPI;

// ══════════════════════════════════════════════════════════════════════
// ASRAPI · 语音识别 API 调用模块 v1.0
// 与 GlobalAPI（聊天）、MiniMax（TTS）、VisionAPI（视觉）完全独立
// 使用 OpenAI 兼容 /v1/audio/transcriptions 接口，适配
// 硅基流动 SenseVoice、Groq Whisper、OpenAI Whisper、阿里 Paraformer 等
// ══════════════════════════════════════════════════════════════════════
const ASRAPI = (() => {
    const KEY = 'phone_asr_cfg';

    const getConfig = () => {
        try { return JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch(e) { return {}; }
    };
    const isConfigured = () => {
        const c = getConfig();
        return !!(c.apiKey && c.baseUrl && c.model);
    };

    // 把 baseUrl 规范成 audio/transcriptions endpoint
    const buildEndpoint = (baseUrl) => {
        let url = (baseUrl || '').replace(/\/+$/, '');
        if (/\/audio\/transcriptions$/.test(url)) return url;
        if (/\/v\d+$/.test(url) || /\/(paas|compatible-mode|openai|api\/v\d+)/.test(url)) {
            return url + '/audio/transcriptions';
        }
        return url + '/v1/audio/transcriptions';
    };

    // 将 Blob 转为 WAV（16kHz mono 16bit PCM）—— 多数 ASR 要求此格式
    const toWavBlob = async (audioBlob) => {
        const ctx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
        const arrayBuffer = await audioBlob.arrayBuffer();
        const audioBuffer = await ctx.decodeAudioData(arrayBuffer);
        // 重采样到 16kHz mono
        const offlineCtx = new OfflineAudioContext(1, 16000 * audioBuffer.duration, 16000);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start(0);
        const rendered = await offlineCtx.startRendering();
        // 编码 WAV
        const length = rendered.length;
        const buf = new ArrayBuffer(44 + length * 2);
        const view = new DataView(buf);
        const ws = (o, s) => { for (let i = 0; i < s.length; i++) view.setUint8(o + i, s.charCodeAt(i)); };
        ws(0, 'RIFF'); view.setUint32(4, 36 + length * 2, true); ws(8, 'WAVE');
        ws(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
        view.setUint16(22, 1, true); view.setUint32(24, 16000, true);
        view.setUint32(28, 16000 * 2, true); view.setUint16(32, 2, true); view.setUint16(34, 16, true);
        ws(36, 'data'); view.setUint32(40, length * 2, true);
        // 写入 PCM 16bit
        for (let i = 0; i < length; i++) {
            const s = Math.max(-1, Math.min(1, rendered.getChannelData(0)[i]));
            view.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7FFF, true);
        }
        return new Blob([buf], { type: 'audio/wav' });
    };

    // 主调用方法
    // audioBlob: 浏览器录制的音频 Blob（任意格式）
    // opts: { language?, prompt? }
    // 返回: { text: '识别文字' }
    const transcribe = async (audioBlob, opts = {}) => {
        const cfg = getConfig();
        if (!cfg.apiKey || !cfg.baseUrl || !cfg.model) {
            throw new Error('ASR 语音识别 API 尚未配置（设置 → 克隆音色设置 → 语音识别 API 配置）');
        }
        // 转为标准 WAV
        const wavBlob = await toWavBlob(audioBlob);
        const fd = new FormData();
        fd.append('file', wavBlob, 'recording.wav');
        fd.append('model', cfg.model);
        if (opts.language || cfg.language) fd.append('language', opts.language || cfg.language);
        if (opts.prompt) fd.append('prompt', opts.prompt);
        fd.append('response_format', 'json');

        const endpoint = buildEndpoint(cfg.baseUrl);
        const resp = await fetch(endpoint, {
            method: 'POST',
            headers: { 'Authorization': 'Bearer ' + cfg.apiKey },
            body: fd
        });
        if (!resp.ok) {
            const text = await resp.text().catch(() => '');
            throw new Error('ASR HTTP ' + resp.status + ' ' + text.slice(0, 200));
        }
        const data = await resp.json();
        if (typeof data.text !== 'string') throw new Error('ASR 返回格式异常：缺少 text 字段');
        return { text: data.text.trim() };
    };

    return { getConfig, isConfigured, transcribe, toWavBlob };
})();
window.ASRAPI = ASRAPI;

