// ══════════════════════════════════════════════════════════════════════
// SystemCenter · 通知中心 + 控制中心 v1.0
// 顶部左侧下滑=通知中心 ; 顶部右侧下滑=控制中心
// ══════════════════════════════════════════════════════════════════════
const SystemCenter = (() => {

    // ── 控制中心开关状态（持久化）──
    const cc = {
        airplane: false, wifi: true, bluetooth: true,
        flashlight: false, darkMode: false, lock: false,
        brightness: 70, volume: 60
    };
    const CKEY = 'syscenter_cc_v1';
    const ccLoad = () => { try { const r=localStorage.getItem(CKEY); if(r) Object.assign(cc, JSON.parse(r)); } catch(e){} };
    const ccSave = () => { try { localStorage.setItem(CKEY, JSON.stringify(cc)); } catch(e){} };
    ccLoad();

    // ── 通知数据（按时间倒序，软件分组）──
    // 每条: { app, appName, sender, title, body, time(ts), id }
    let notifications = [];
    const NKEY = 'syscenter_notif_v1';
    const nLoad = () => {
        try { const r=localStorage.getItem(NKEY); if(r) { const p=JSON.parse(r); notifications = Array.isArray(p) ? p : []; } } catch(e){ notifications = []; }
        if (!notifications.length) seedNotifications();
    };
    const nSave = () => { try { localStorage.setItem(NKEY, JSON.stringify(notifications)); } catch(e){} };

    // 初始示例通知（微博/论坛/朋友圈/短信/日程）
    function seedNotifications() { /* [AJ] 不再放 7 条示例通知：没有通知就是空列表 */ notifications = []; nSave(); }
    nLoad();

    // 对外：新增一条通知
    const pushNotification = (n) => {
        notifications.unshift(Object.assign({ id:'n'+Date.now(), time:Date.now() }, n));
        if (notifications.length > 50) notifications.pop();
        nSave();
        renderNotifList();
    };

    // ── [AS组] 供离线通知层读写：列表 / 未读数 / 标已读 / 单条删除 / 全部清除 / 旧数据规范化 ──
    // 旧数据（AS 合入前已存的通知）没有 read 字段，缺省按已读算，避免旧通知永远顶着未读角标。
    const listNotifications = () => notifications.slice();
    const unreadCount = () => notifications.filter(n => n.read === false).length;
    const normalizeRead = () => { let ch = false; notifications.forEach(n => { if (n.read === undefined) { n.read = true; ch = true; } }); if (ch) { nSave(); renderNotifList(); } return true; };
    const markRead = (id) => { const n = notifications.find(x => x.id === id); if (!n) return false; n.read = true; nSave(); renderNotifList(); return true; };
    const markAllRead = () => { notifications.forEach(n => { n.read = true; }); nSave(); renderNotifList(); return true; };
    const removeNotification = (id) => { const before = notifications.length; notifications = notifications.filter(n => n.id !== id); if (notifications.length !== before) { nSave(); renderNotifList(); return true; } return false; };
    const clearNotifications = () => { notifications = []; nSave(); renderNotifList(); return true; };

    // 相对时间格式化
    const fmtTime = (ts) => {
        const diff = Date.now() - ts;
        if (diff < 60000) return '刚刚';
        if (diff < 3600000) return Math.floor(diff/60000) + '分钟前';
        if (diff < 86400000) return Math.floor(diff/3600000) + '小时前';
        return Math.floor(diff/86400000) + '天前';
    };

    // ── 注入 CSS ──
    const injectCSS = () => {
        if (document.getElementById('syscenter-css')) return;
        const s = document.createElement('style');
        s.id = 'syscenter-css';
        s.textContent = `
        /* 手势触发热区 */
        .sc-trigger { position:absolute; top:0; height:32px; z-index:50000; }
        .sc-trigger-left { left:0; width:55%; }
        .sc-trigger-right { right:0; width:45%; }

        /* 通用面板 */
        .sc-panel {
            position:absolute; left:0; width:100%; height:100%;
            z-index:60000; top:0;
            transform:translateY(-100%);
            transition:transform .34s cubic-bezier(.32,.72,.24,1);
            will-change:transform;
        }
        .sc-panel.show { transform:translateY(0); }

        /* ───── 通知中心 ───── */
        .sc-notif {
            background:rgba(20,20,24,0.55);
            backdrop-filter:blur(16px) saturate(180%);
            -webkit-backdrop-filter:blur(16px) saturate(180%);
            display:flex; flex-direction:column;
        }
        .sc-notif-head {
            text-align:center; color:#fff; padding:54px 0 10px;
            flex-shrink:0;
        }
        .sc-notif-time { font-size:62px; font-weight:600; line-height:1;
            text-shadow:0 2px 12px rgba(0,0,0,0.4); }
        .sc-notif-date { font-size:16px; margin-top:6px; opacity:0.9; }
        .sc-notif-title-row {
            display:flex; justify-content:space-between; align-items:center;
            padding:14px 18px 8px; color:#fff;
        }
        .sc-notif-title-row .t { font-size:19px; font-weight:700; }
        .sc-notif-clear {
            font-size:13px; background:rgba(255,255,255,0.22);
            padding:5px 12px; border-radius:14px; cursor:pointer;
        }
        .sc-notif-list {
            flex:1; overflow-y:auto; padding:4px 14px 30px;
        }
        .sc-notif-group-label {
            color:rgba(255,255,255,0.65); font-size:13px; font-weight:600;
            padding:10px 6px 6px;
        }
        .sc-notif-card {
            background:rgba(245,245,247,0.92);
            border-radius:16px; padding:12px 14px; margin-bottom:8px;
            position:relative; overflow:hidden;
            transition:transform .2s;
        }
        .sc-notif-card-inner { transition:transform .25s; }
        .sc-notif-card.swiped .sc-notif-card-inner { transform:translateX(-72px); }
        .sc-notif-card-head {
            display:flex; align-items:center; gap:8px; margin-bottom:4px;
        }
        .sc-notif-app-ico {
            width:20px; height:20px; border-radius:5px; flex-shrink:0;
            display:flex; align-items:center; justify-content:center;
            font-size:12px; color:#fff;
        }
        .sc-notif-sender { font-size:12px; color:#8a8a8e; flex:1;
            white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
        .sc-notif-time-ago { font-size:11px; color:#b0b0b3; }
        .sc-notif-body-title { font-size:14px; font-weight:600; color:#1a1a1a; }
        .sc-notif-body-text { font-size:13px; color:#3a3a3c; margin-top:1px;
            line-height:1.4; }
        .sc-notif-del-btn {
            position:absolute; right:0; top:0; height:100%; width:72px;
            background:#ff3b30; color:#fff; display:flex;
            align-items:center; justify-content:center; font-size:13px;
            cursor:pointer;
        }
        .sc-notif-empty {
            text-align:center; color:rgba(255,255,255,0.55);
            padding:60px 0; font-size:14px;
        }
        .sc-handle {
            width:36px; height:5px; border-radius:3px;
            background:rgba(255,255,255,0.5); margin:8px auto 0;
            flex-shrink:0;
        }

        /* ───── 控制中心 ───── */
        .sc-control {
            background:rgba(30,30,34,0.45);
            backdrop-filter:blur(17px) saturate(180%);
            -webkit-backdrop-filter:blur(17px) saturate(180%);
            padding:54px 14px 20px;
            display:flex; flex-direction:column; gap:11px;
            overflow-y:auto;
        }
        .sc-cc-handle { width:36px; height:5px; border-radius:3px;
            background:rgba(255,255,255,0.5); margin:-44px auto 8px; }
        .sc-cc-grid { display:grid; grid-template-columns:1fr 1fr; gap:11px; }
        .sc-cc-tile {
            background:rgba(255,255,255,0.16);
            border-radius:18px; padding:14px;
        }
        /* 4连开关块 */
        .sc-cc-conn { display:grid; grid-template-columns:1fr 1fr;
            gap:14px; align-items:center; }
        .sc-cc-btn {
            display:flex; align-items:center; gap:9px;
            cursor:pointer; min-height:44px;
        }
        .sc-cc-btn-ico {
            width:44px; height:44px; border-radius:50%;
            background:rgba(120,120,128,0.5);
            display:flex; align-items:center; justify-content:center;
            transition:background .2s;
        }
        .sc-cc-btn.on .sc-cc-btn-ico { background:#0a84ff; }
        .sc-cc-btn.on.green .sc-cc-btn-ico { background:#30d158; }
        .sc-cc-btn.on.orange .sc-cc-btn-ico { background:#ff9f0a; }
        .sc-cc-btn-label { color:#fff; font-size:12px; line-height:1.2; }
        .sc-cc-btn-state { color:rgba(255,255,255,0.6); font-size:10px; }
        /* 单图标方块 */
        .sc-cc-square {
            background:rgba(255,255,255,0.16);
            border-radius:18px;
            display:flex; flex-direction:column;
            align-items:center; justify-content:center; gap:6px;
            min-height:88px; cursor:pointer;
        }
        .sc-cc-square.on { background:#fff; }
        .sc-cc-square-ico { width:30px; height:30px;
            display:flex; align-items:center; justify-content:center; }
        .sc-cc-square-label { font-size:11px; color:#fff; }
        .sc-cc-square.on .sc-cc-square-label { color:#000; }
        /* 滑块 */
        .sc-cc-slider {
            background:rgba(255,255,255,0.16);
            border-radius:18px; padding:0; overflow:hidden;
            height:150px; position:relative; cursor:pointer;
        }
        .sc-cc-slider-fill {
            position:absolute; bottom:0; left:0; width:100%;
            background:#fff; transition:height .12s;
        }
        .sc-cc-slider-ico {
            position:absolute; bottom:14px; left:50%;
            transform:translateX(-50%); z-index:2;
            color:#888;
        }
        .sc-cc-sliders-row { display:grid; grid-template-columns:1fr 1fr; gap:11px; }
        `;
        document.head.appendChild(s);
    };

    // ── 通知中心 HTML ──
    const buildNotifPanel = () => {
        return `
        <div class="sc-notif-head">
            <div class="sc-notif-time" id="sc-notif-time">--:--</div>
            <div class="sc-notif-date" id="sc-notif-date">--</div>
        </div>
        <div class="sc-notif-title-row">
            <span class="t">通知中心 <span id="sc-notif-count" style="font-size:13px;font-weight:400;opacity:.75;"></span></span>
            <span class="sc-notif-clear" id="sc-notif-clear">清除全部</span>
        </div>
        <div class="sc-notif-list" id="sc-notif-list"></div>
        <div class="sc-notif-note">本机通知为本地通知，离线可用；不是系统级推送，关掉手机就不会响。</div>
        <div class="sc-handle"></div>`;
    };

    // 软件图标色
    const APP_COLOR = {
        wechat:'#07c160', sms:'#34c759', weibo:'#e6162d',
        forum:'#ff9500', moments:'#07c160', schedule:'#ff3b30', habits:'#5b8c5a'
    };
    const APP_GLYPH = {
        wechat:'<svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11.5a8.5 8.5 0 0 1-12.4 7.5L3 21l2-5.6A8.5 8.5 0 1 1 21 11.5Z"/></svg>', sms:'<svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></svg>', weibo:'微', forum:'坛', moments:'圈', schedule:'<svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="5" width="17" height="16" rx="2"/><path d="M3.5 10h17M8 3v4m8-4v4"/></svg>', habits:'<svg class="xwl-ui-vector" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19C5 9 12 4 20 4c0 8-5 15-15 15Z"/><path d="M5 19c3-6 7-9 11-11"/></svg>'
    };

    // 渲染通知列表（按时间倒序 + 软件分组）
    const renderNotifList = () => {
        const list = document.getElementById('sc-notif-list');
        if (!list) return;
        const _cnt = document.getElementById('sc-notif-count');
        if (_cnt) { const _u = notifications.filter(n => n.read === false).length; _cnt.textContent = _u ? ('（' + _u + ' 条未读）') : ''; }
        if (!notifications.length) {
            list.innerHTML = `<div class="sc-notif-empty">没有新通知</div>`;
            return;
        }
        // 先按时间倒序
        const sorted = [...notifications].sort((a,b) => b.time - a.time);
        // 按 app 分组（保持组内时间倒序，组按最新通知排序）
        const groups = {};
        sorted.forEach(n => { (groups[n.app] = groups[n.app] || []).push(n); });
        const groupOrder = Object.keys(groups).sort((a,b) =>
            groups[b][0].time - groups[a][0].time);

        list.innerHTML = groupOrder.map(app => {
            const items = groups[app];
            return `<div class="sc-notif-group-label">${items[0].appName}</div>` +
                items.map(n => `
                <div class="sc-notif-card${n.read === false ? ' sc-notif-unread' : ''}" data-nid="${n.id}">
                    <div class="sc-notif-del-btn" data-del="${n.id}">清除</div>
                    <div class="sc-notif-card-inner" data-open="${n.id}">
                        <div class="sc-notif-card-head">
                            <div class="sc-notif-app-ico" style="background:${APP_COLOR[n.app]||'#888'};">${APP_GLYPH[n.app]||'•'}</div>
                            <span class="sc-notif-sender">${n.sender}</span>
                            <span class="sc-notif-time-ago">${fmtTime(n.time)}</span>
                        </div>
                        <div class="sc-notif-body-title">${n.title}</div>
                        <div class="sc-notif-body-text">${n.body}</div>
                    </div>
                </div>`).join('');
        }).join('');
    };

    // ── 控制中心 HTML ──
    const buildControlPanel = () => {
        return `
        <div class="sc-cc-handle"></div>
        <!-- 连接开关 4 连块 -->
        <div class="sc-cc-tile">
            <div class="sc-cc-conn">
                <div class="sc-cc-btn ${cc.airplane?'on orange':''}" data-cc="airplane">
                    <div class="sc-cc-btn-ico">
                        <svg viewBox="0 0 24 24" width="20" fill="#fff"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L11 19v-5.5z"/></svg>
                    </div>
                    <div><div class="sc-cc-btn-label">飞行模式</div><div class="sc-cc-btn-state" id="sc-st-airplane">${cc.airplane?'开':'关'}</div></div>
                </div>
                <div class="sc-cc-btn ${cc.wifi?'on':''}" data-cc="wifi">
                    <div class="sc-cc-btn-ico">
                        <svg viewBox="0 0 24 24" width="20" fill="#fff"><path d="M12 18a2 2 0 1 0 0 4 2 2 0 0 0 0-4zM5 12.5a10 10 0 0 1 14 0l-2 2a7 7 0 0 0-10 0zM1.5 9A15 15 0 0 1 22.5 9l-2 2a12 12 0 0 0-17 0z"/></svg>
                    </div>
                    <div><div class="sc-cc-btn-label">无线局域网</div><div class="sc-cc-btn-state" id="sc-st-wifi">${cc.wifi?'已连接':'关'}</div></div>
                </div>
                <div class="sc-cc-btn ${cc.bluetooth?'on':''}" data-cc="bluetooth">
                    <div class="sc-cc-btn-ico">
                        <svg viewBox="0 0 24 24" width="16" fill="#fff"><path d="M12 2l5 5-4 4 4 4-5 5v-9l-3 3-1.5-1.5L10 13 6.5 9.5 8 8l3 3V2z"/></svg>
                    </div>
                    <div><div class="sc-cc-btn-label">蓝牙</div><div class="sc-cc-btn-state" id="sc-st-bluetooth">${cc.bluetooth?'开':'关'}</div></div>
                </div>
                <div class="sc-cc-btn ${cc.darkMode?'on':''}" data-cc="darkMode">
                    <div class="sc-cc-btn-ico">
                        <svg viewBox="0 0 24 24" width="19" fill="#fff"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>
                    </div>
                    <div><div class="sc-cc-btn-label">深色模式</div><div class="sc-cc-btn-state" id="sc-st-darkMode">${cc.darkMode?'开':'关'}</div></div>
                </div>
            </div>
        </div>

        <!-- 亮度 + 音量 滑块 -->
        <div class="sc-cc-sliders-row">
            <div class="sc-cc-slider" data-slider="brightness">
                <div class="sc-cc-slider-fill" id="sc-fill-brightness" style="height:${cc.brightness}%;"></div>
                <div class="sc-cc-slider-ico">
                    <svg viewBox="0 0 24 24" width="22" fill="currentColor"><circle cx="12" cy="12" r="5"/><g stroke="currentColor" stroke-width="2"><path d="M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M20 4l-2 2M6 18l-2 2"/></g></svg>
                </div>
            </div>
            <div class="sc-cc-slider" data-slider="volume">
                <div class="sc-cc-slider-fill" id="sc-fill-volume" style="height:${cc.volume}%;"></div>
                <div class="sc-cc-slider-ico">
                    <svg viewBox="0 0 24 24" width="22" fill="currentColor"><path d="M11 5L6 9H2v6h4l5 4zM15.5 8.5a5 5 0 0 1 0 7M18.5 6a9 9 0 0 1 0 12"/></svg>
                </div>
            </div>
        </div>

        <!-- 手电筒 / 屏幕锁定 / 计算器 / 相机 -->
        <div class="sc-cc-grid">
            <div class="sc-cc-square ${cc.flashlight?'on':''}" data-cc="flashlight">
                <div class="sc-cc-square-ico">
                    <svg viewBox="0 0 24 24" width="26" fill="${cc.flashlight?'#000':'#fff'}" id="sc-ico-flashlight"><path d="M7 2h10v4l-3 3v13h-4V9L7 6V2z"/></svg>
                </div>
                <div class="sc-cc-square-label">手电筒</div>
            </div>
            <div class="sc-cc-square ${cc.lock?'on':''}" data-cc="lock">
                <div class="sc-cc-square-ico">
                    <svg viewBox="0 0 24 24" width="24" fill="${cc.lock?'#000':'#fff'}" id="sc-ico-lock"><path d="M6 10V8a6 6 0 0 1 12 0v2h1a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-9a1 1 0 0 1 1-1zm2 0h8V8a4 4 0 0 0-8 0z"/></svg>
                </div>
                <div class="sc-cc-square-label">屏幕锁定</div>
            </div>
            <div class="sc-cc-square" data-act="calculator">
                <div class="sc-cc-square-ico">
                    <svg viewBox="0 0 24 24" width="24" fill="#fff"><rect x="4" y="2" width="16" height="20" rx="3"/><rect x="7" y="5" width="10" height="4" rx="1" fill="#1c1c1e"/><circle cx="8.5" cy="13" r="1.3" fill="#1c1c1e"/><circle cx="12" cy="13" r="1.3" fill="#1c1c1e"/><circle cx="15.5" cy="13" r="1.3" fill="#1c1c1e"/><circle cx="8.5" cy="17" r="1.3" fill="#1c1c1e"/><circle cx="12" cy="17" r="1.3" fill="#1c1c1e"/><circle cx="15.5" cy="17" r="1.3" fill="#1c1c1e"/></svg>
                </div>
                <div class="sc-cc-square-label">计算器</div>
            </div>
            <div class="sc-cc-square" data-act="camera">
                <div class="sc-cc-square-ico">
                    <svg viewBox="0 0 24 24" width="26" fill="#fff"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4" fill="#1c1c1e"/></svg>
                </div>
                <div class="sc-cc-square-label">相机</div>
            </div>
        </div>`;
    };

    // ── 状态实时刷新 ──
    const refreshControlUI = () => {
        ['airplane','wifi','bluetooth','darkMode'].forEach(k => {
            const btn = document.querySelector(`.sc-cc-btn[data-cc="${k}"]`);
            if (btn) {
                btn.classList.toggle('on', cc[k]);
                if (k==='airplane') btn.classList.toggle('orange', cc[k]);
            }
            const st = document.getElementById('sc-st-'+k);
            if (st) st.textContent = cc[k] ? (k==='wifi'?'已连接':'开') : '关';
        });
        ['flashlight','lock'].forEach(k => {
            const sq = document.querySelector(`.sc-cc-square[data-cc="${k}"]`);
            if (sq) sq.classList.toggle('on', cc[k]);
            const ico = document.getElementById('sc-ico-'+k);
            if (ico) ico.setAttribute('fill', cc[k]?'#000':'#fff');
        });
        const bf = document.getElementById('sc-fill-brightness');
        if (bf) bf.style.height = cc.brightness + '%';
        const vf = document.getElementById('sc-fill-volume');
        if (vf) vf.style.height = cc.volume + '%';
    };

    // 应用系统级副作用
    const applyEffect = (key) => {
        const shell = document.getElementById('sys-shell');
        if (key === 'brightness' && shell) {
            shell.style.filter = `brightness(${0.35 + cc.brightness/100*0.75})`;
        }
        if (key === 'darkMode' && shell) {
            // 轻度深色：给桌面叠一层
            let dm = document.getElementById('sc-darkmode-layer');
            if (cc.darkMode) {
                if (!dm) {
                    dm = document.createElement('div');
                    dm.id = 'sc-darkmode-layer';
                    dm.style.cssText = 'position:absolute;inset:0;background:rgba(0,0,0,0.32);z-index:30;pointer-events:none;';
                    shell.appendChild(dm);
                }
            } else if (dm) dm.remove();
        }
        if (key === 'flashlight') {
            let fl = document.getElementById('sc-flashlight-layer');
            if (cc.flashlight) {
                if (!fl) {
                    fl = document.createElement('div');
                    fl.id = 'sc-flashlight-layer';
                    fl.style.cssText = 'position:absolute;inset:0;background:rgba(255,255,240,0.0);z-index:1;pointer-events:none;box-shadow:inset 0 0 120px rgba(255,255,200,0.25);';
                    shell.appendChild(fl);
                }
            } else if (fl) fl.remove();
        }
        if (key === 'lock' && cc.lock) {
            // 触发锁屏
            cc.lock = false; ccSave();
            hideAll();
            const ls = document.getElementById('sys-lockscreen-layer');
            const shellEl = document.getElementById('sys-shell');
            if (ls) ls.classList.add('sys-active');
            if (shellEl) shellEl.classList.remove('sys-unlocked');
        }
    };

    // ── 面板显隐 ──
    let activePanel = null;
    const showPanel = (which) => {
        const panel = document.getElementById('sc-panel-' + which);
        if (!panel) return;
        // 先隐藏另一个
        if (activePanel && activePanel !== which) hidePanel(activePanel);
        panel.classList.add('show');
        activePanel = which;
        if (which === 'notif') { renderNotifList(); updateNotifClock(); }
        if (which === 'control') refreshControlUI();
        if (navigator.vibrate) navigator.vibrate(8);
    };
    const hidePanel = (which) => {
        const panel = document.getElementById('sc-panel-' + which);
        if (panel) panel.classList.remove('show');
        if (activePanel === which) activePanel = null;
    };
    const hideAll = () => { hidePanel('notif'); hidePanel('control'); };

    // 通知中心时钟
    const updateNotifClock = () => {
        const t = document.getElementById('sc-notif-time');
        const d = document.getElementById('sc-notif-date');
        const now = new Date();
        if (t) t.textContent = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
        if (d) {
            const wd = ['周日','周一','周二','周三','周四','周五','周六'][now.getDay()];
            d.textContent = `${now.getMonth()+1}月${now.getDate()}日 ${wd}`;
        }
    };

    // ── 初始化 ──
    const init = () => {
        injectCSS();
        const shell = document.getElementById('sys-shell');
        if (!shell) return;

        // 创建两个面板
        const notifPanel = document.createElement('div');
        notifPanel.id = 'sc-panel-notif';
        notifPanel.className = 'sc-panel sc-notif';
        notifPanel.innerHTML = buildNotifPanel();
        shell.appendChild(notifPanel);

        const ctrlPanel = document.createElement('div');
        ctrlPanel.id = 'sc-panel-control';
        ctrlPanel.className = 'sc-panel sc-control';
        ctrlPanel.innerHTML = buildControlPanel();
        shell.appendChild(ctrlPanel);

        // 创建顶部两个手势热区
        const tL = document.createElement('div');
        tL.className = 'sc-trigger sc-trigger-left';
        const tR = document.createElement('div');
        tR.className = 'sc-trigger sc-trigger-right';
        shell.appendChild(tL);
        shell.appendChild(tR);

        bindGestures(tL, tR, notifPanel, ctrlPanel);
        bindNotifEvents(notifPanel);
        bindControlEvents(ctrlPanel);

        // 时钟每分钟刷新
        setInterval(() => { if (activePanel === 'notif') updateNotifClock(); }, 10000);
        // 启动时应用一次亮度/深色
        applyEffect('brightness');
        if (cc.darkMode) applyEffect('darkMode');
    };

    // ── 手势绑定 ──
    const bindGestures = (tL, tR, notifPanel, ctrlPanel) => {
        let startY = 0, startX = 0, dragging = null, swiping = false;
        const onStart = (which, x, y) => {
            // 锁屏时不允许呼出
            const shell = document.getElementById('sys-shell');
            if (shell && !shell.classList.contains('sys-unlocked')) return;
            startY = y; startX = x; dragging = which; swiping = true;
        };
        // 顶部热区下滑
        tL.addEventListener('touchstart', e => onStart('notif', e.touches[0].clientX, e.touches[0].clientY), {passive:true});
        tR.addEventListener('touchstart', e => onStart('control', e.touches[0].clientX, e.touches[0].clientY), {passive:true});
        tL.addEventListener('mousedown', e => onStart('notif', e.clientX, e.clientY));
        tR.addEventListener('mousedown', e => onStart('control', e.clientX, e.clientY));

        const onMove = (y) => {
            if (!swiping || !dragging) return;
            if (y - startY > 45) {
                showPanel(dragging);
                swiping = false; dragging = null;
            }
        };
        window.addEventListener('touchmove', e => onMove(e.touches[0].clientY), {passive:true});
        window.addEventListener('mousemove', e => { if(swiping) onMove(e.clientY); });
        window.addEventListener('touchend', () => { swiping=false; dragging=null; });
        window.addEventListener('mouseup', () => { swiping=false; dragging=null; });

        // 面板内上滑收起
        [notifPanel, ctrlPanel].forEach(panel => {
            let pStartY = 0, pSwipe = false;
            panel.addEventListener('touchstart', e => {
                pStartY = e.touches[0].clientY; pSwipe = true;
            }, {passive:true});
            panel.addEventListener('touchmove', e => {
                if (!pSwipe) return;
                if (pStartY - e.touches[0].clientY > 50) {
                    hideAll(); pSwipe = false;
                }
            }, {passive:true});
            panel.addEventListener('touchend', () => { pSwipe = false; });
            // PC：点 handle 收起
            const h = panel.querySelector('.sc-handle, .sc-cc-handle');
            if (h) h.addEventListener('click', hideAll);
        });
    };

    // ── 通知中心事件 ──
    const bindNotifEvents = (panel) => {
        // 清除全部
        panel.querySelector('#sc-notif-clear')?.addEventListener('click', () => {
            notifications = []; nSave(); renderNotifList();
        });
        // 列表委托：左滑 / 点击 / 删除
        const list = panel.querySelector('#sc-notif-list');
        let cardStartX = 0, swipeCard = null;
        list.addEventListener('touchstart', e => {
            const card = e.target.closest('.sc-notif-card');
            if (card) { cardStartX = e.touches[0].clientX; swipeCard = card; }
        }, {passive:true});
        list.addEventListener('touchmove', e => {
            if (!swipeCard) return;
            const dx = e.touches[0].clientX - cardStartX;
            if (dx < -30) swipeCard.classList.add('swiped');
            else if (dx > 30) swipeCard.classList.remove('swiped');
        }, {passive:true});
        list.addEventListener('touchend', () => { swipeCard = null; });
        // 点击：删除按钮 / 打开通知
        list.addEventListener('click', e => {
            const delId = e.target.closest('[data-del]')?.getAttribute('data-del');
            if (delId) {
                notifications = notifications.filter(n => n.id !== delId);
                nSave(); renderNotifList();
                return;
            }
            const openId = e.target.closest('[data-open]')?.getAttribute('data-open');
            if (openId) {
                const card = e.target.closest('.sc-notif-card');
                if (card && card.classList.contains('swiped')) {
                    card.classList.remove('swiped'); return;
                }
                openNotification(openId);
            }
        });
    };

    // 点通知 → 跳转对应 APP（[AS组] 标已读 + 补全 app 映射 + focus 等伪目标走 GroupAS）
    const openNotification = (nid) => {
        const n = notifications.find(x => x.id === nid);
        if (!n) return;
        n.read = true; nSave(); renderNotifList();
        hideAll();
        if (typeof AppManager === 'undefined') return;
        // 映射通知 app → 实际可启动 APP（D 组已接 weibo 等；AS 补全其余）/* GROUP-FIX7：schedule 已删 */
        const appMap = {
            wechat:'wechat', sms:'sms', moments:'wechat',
            weibo:'weibo', forum:'forum',
            memo:'memo', phone:'phone', album:'album', weather:'weather',
            music:'music', script:'script', cinema:'cinema', novel:'novel',
            cike:'cike', guichao:'guichao', settings:'settings'
        };
        const target = n.targetApp || appMap[n.app];
        if (!target) return;
        // focus 不是注册 app，走 GroupAS.openTarget（番茄面板）
        if (target === 'focus') { try { if (window.GroupAS) window.GroupAS.openTarget(n); } catch (e) {} return; }
        if (typeof AppRegistry !== 'undefined' && !AppRegistry[target]) return; /* GROUP-FIX7：目标 app 未注册（已删，如旧通知里的 schedule）时不跳 */
        try { AppManager.launch(target); } catch (e) {}
    };

    // ── 控制中心事件 ──
    const bindControlEvents = (panel) => {
        // 开关类
        panel.addEventListener('click', e => {
            const ccBtn = e.target.closest('[data-cc]');
            if (ccBtn) {
                const key = ccBtn.getAttribute('data-cc');
                cc[key] = !cc[key];
                ccSave();
                refreshControlUI();
                applyEffect(key);
                if (navigator.vibrate) navigator.vibrate(6);
                return;
            }
            // 计算器 / 相机入口
            const act = e.target.closest('[data-act]')?.getAttribute('data-act');
            if (act === 'calculator') { hideAll(); openCalculator(); }
            else if (act === 'camera') {
                // 真实相机：调起系统拍照，拍完可预览、设为壁纸（原先错误地打开了设置页）
                hideAll();
                const inp = document.createElement('input');
                inp.type = 'file'; inp.accept = 'image/*'; inp.setAttribute('capture', 'environment');
                inp.style.display = 'none';
                document.body.appendChild(inp);
                inp.onchange = () => {
                    const f = inp.files && inp.files[0];
                    document.body.removeChild(inp);
                    if (!f) return;
                    const r = new FileReader();
                    r.onload = (ev) => {
                        const url = ev.target.result;
                        const ov = document.createElement('div');
                        ov.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;';
                        ov.innerHTML = '<img src="' + url + '" style="max-width:100%;max-height:82%;object-fit:contain;border-radius:8px;">' +
                            '<div style="display:flex;gap:12px;margin-top:16px;">' +
                            '<button id="cc-cam-wallpaper" style="padding:10px 18px;border-radius:20px;border:none;background:#34C759;color:#fff;font-size:15px;">设为壁纸</button>' +
                            '<button id="cc-cam-close" style="padding:10px 18px;border-radius:20px;border:none;background:rgba(255,255,255,0.2);color:#fff;font-size:15px;">关闭</button></div>';
                        ov.querySelector('#cc-cam-close').onclick = () => ov.remove();
                        ov.querySelector('#cc-cam-wallpaper').onclick = () => {
                            try { if (typeof SystemStore !== 'undefined') SystemStore.set('wallpaper', url); } catch(e){}
                            const shell = document.getElementById('sys-shell');
                            if (shell) shell.style.backgroundImage = 'url("' + url + '")';
                            ov.remove();
                        };
                        document.body.appendChild(ov);
                    };
                    r.readAsDataURL(f);
                };
                inp.click();
            }
        });
        // 滑块拖动
        panel.querySelectorAll('.sc-cc-slider').forEach(sl => {
            const key = sl.getAttribute('data-slider');
            const setFromY = (clientY) => {
                const rect = sl.getBoundingClientRect();
                let pct = Math.round((1 - (clientY - rect.top) / rect.height) * 100);
                pct = Math.max(0, Math.min(100, pct));
                cc[key] = pct;
                ccSave();
                const fill = document.getElementById('sc-fill-'+key);
                if (fill) fill.style.height = pct + '%';
                applyEffect(key);
            };
            let sliding = false;
            sl.addEventListener('touchstart', e => { sliding=true; setFromY(e.touches[0].clientY); }, {passive:true});
            sl.addEventListener('touchmove', e => { if(sliding) setFromY(e.touches[0].clientY); }, {passive:true});
            sl.addEventListener('touchend', () => { sliding=false; });
            sl.addEventListener('mousedown', e => { sliding=true; setFromY(e.clientY); });
            window.addEventListener('mousemove', e => { if(sliding) setFromY(e.clientY); });
            window.addEventListener('mouseup', () => { sliding=false; });
        });
    };

    // 简易计算器弹窗
    const openCalculator = () => {
        let calc = document.getElementById('sc-calc-modal');
        if (calc) { calc.style.display='flex'; return; }
        calc = document.createElement('div');
        calc.id = 'sc-calc-modal';
        calc.style.cssText = 'position:absolute;inset:0;z-index:70000;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;';
        calc.innerHTML = `
        <div style="width:280px;background:#1c1c1e;border-radius:20px;padding:18px;">
            <div id="sc-calc-disp" style="color:#fff;font-size:42px;text-align:right;padding:14px 8px;font-weight:300;min-height:50px;">0</div>
            <div id="sc-calc-keys" style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;">
                ${['C','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='].map(k => {
                    const op = ['÷','×','−','+','='].includes(k);
                    const fn = ['C','±','%'].includes(k);
                    const wide = k==='0';
                    return `<div data-k="${k}" style="${wide?'grid-column:span 2;':''}height:58px;border-radius:30px;display:flex;align-items:center;justify-content:center;font-size:24px;cursor:pointer;background:${op?'#ff9f0a':fn?'#a5a5a5':'#333'};color:${fn?'#000':'#fff'};">${k}</div>`;
                }).join('')}
            </div>
            <div data-k="close" style="text-align:center;color:#888;margin-top:14px;cursor:pointer;font-size:14px;">关闭</div>
        </div>`;
        (document.getElementById('sys-shell') || document.body).appendChild(calc);
        // 计算逻辑
        let cur='0', prev=null, op=null, fresh=true;
        const disp = calc.querySelector('#sc-calc-disp');
        const upd = () => disp.textContent = cur;
        calc.querySelector('#sc-calc-keys').addEventListener('click', e => {
            const k = e.target.getAttribute('data-k');
            if (!k) return;
            if (/[0-9]/.test(k)) { cur = (fresh||cur==='0')?k:cur+k; fresh=false; }
            else if (k==='.') { if(!cur.includes('.')) cur+='.'; fresh=false; }
            else if (k==='C') { cur='0'; prev=null; op=null; fresh=true; }
            else if (k==='±') cur = String(parseFloat(cur)*-1);
            else if (k==='%') cur = String(parseFloat(cur)/100);
            else if (['+','−','×','÷'].includes(k)) { prev=parseFloat(cur); op=k; fresh=true; }
            else if (k==='=') {
                if(op!==null && prev!==null){
                    const b=parseFloat(cur);
                    let r=prev;
                    if(op==='+')r=prev+b; if(op==='−')r=prev-b;
                    if(op==='×')r=prev*b; if(op==='÷')r=b!==0?prev/b:0;
                    cur=String(Math.round(r*1e8)/1e8); op=null; prev=null; fresh=true;
                }
            }
            upd();
        });
        calc.addEventListener('click', e => {
            if (e.target.getAttribute('data-k')==='close' || e.target===calc) calc.style.display='none';
        });
    };

    // ── [D组] 对外读写开关状态：供旧控制中心双向同步（底层同一键 syscenter_cc_v1）──
    const getCC = () => Object.assign({}, cc);
    const setCC = (key, val) => {
        cc[key] = val; ccSave(); refreshControlUI(); applyEffect(key);
        try { window.dispatchEvent(new CustomEvent('syscenter-cc-changed', { detail: { key: key, value: val, state: Object.assign({}, cc) } })); } catch(e){}
    };
    return {
        init,
        pushNotification,   // 供其它APP推送通知
        hideAll,
        getCC, setCC,
        list: listNotifications, unreadCount, normalizeRead,
        markRead, markAllRead, removeNotification, clearNotifications
    };
})();
window.SystemCenter = SystemCenter;

// ══════════════════════════════════════════════════════════════════════
// WorldBook · 全局世界书中枢
// 世界书 = 给 AI 输出加的约束规则。聊天 / 朋友圈 / 论坛 / 此刻 等所有 AI
// 生成内容前，都会调用 WorldBook.buildContext() 把启用的条目注入提示词。
// 数据由「世界书 APP」(iframe) 通过 postMessage 同步到这里并落地 localStorage。
// ══════════════════════════════════════════════════════════════════════
const WorldBook = (() => {
    const KEY = 'worldbook_global_v1';
    // GROUP-BK: entry = { id, title, badge, content, scope:'global'|'exclusive',
    //           char, keywords:[], trigger:'always'|'keyword', enabled }
    // scope 只剩两种：'global' 全局（所有角色）/ 'exclusive' 专属某角色。旧写法迁移：'local'→'global'，'agent'→'exclusive'。
    let entries = [];

    const load = () => {
        try {
            const raw = localStorage.getItem(KEY);
            if (raw) { const d = JSON.parse(raw); if (Array.isArray(d)) { const before = JSON.stringify(d); entries = normalizeAll(d); if (JSON.stringify(entries) !== before) save(); } }
            // GROUP-WECHAT · 第 10 项：拼写统一收尾——normalizeAll 把遗留 'agent' 归一为 'exclusive' 后，
            // 若存储 JSON 因此变化则回存，使旧拼写收敛（setAll 本来就回存，load 是缺口）。
        } catch(e) { console.warn('WorldBook 读取失败', e); }
    };
    const save = () => {
        try { localStorage.setItem(KEY, JSON.stringify(entries)); }
        catch(e) { console.warn('WorldBook 保存失败', e); }
    };

    // 由世界书 APP 同步进来的全量数据
    const setAll = (arr) => {
        if (Array.isArray(arr)) { entries = normalizeAll(arr); save(); }
    };
    const getAll = () => normalizeAll(entries);

    // GROUP-BK · scope 只剩两种写法：'global'（全局，所有角色）与 'exclusive'（专属某角色）。
    // 旧写法就地迁移，不删用户数据：'local' 与 'global' 同义 → 'global'；'agent'（微信词库卡片旧写法）→ 'exclusive'。
    const LAST_KEY = 'wb_last_injection_v1'; // GROUP-BK 新增的唯一键：最近一次世界书注入记录（可再生，不进备份）
    let lastInjection = null;
    let buildCount = 0;
    // GROUP-WECHAT · 第 10 项：规范拼写只有 'global' / 'exclusive'；'agent' 分支是遗留数据迁移入口，绝不删除。
    const normalizeScope = (s) => {
        if (s === 'exclusive' || s === 'agent') return 'exclusive'; // 迁移入口：遗留 'agent' 归一为 'exclusive'
        return 'global';
    };
    const normalizeAll = (arr) => (Array.isArray(arr) ? arr : []).map((e) => {
        if (!e || typeof e !== 'object') return e;
        const c = Object.assign({}, e);
        c.scope = normalizeScope(e.scope);
        return c;
    });
    const posOf = (e) => (e.position === '角色后' ? 'after' : (e.position === '深度注入' ? 'deep' : 'before'));
    const posLabel = (e) => (posOf(e) === 'after' ? '角色后' : (posOf(e) === 'deep' ? '深度注入' : '角色前'));
    // 命中的条目：scope 过滤 + trigger 过滤。globalOnly 时只取全局条目（角色未知时用，专属条目绝不外泄）。
    const matchEntries = (scene, charName, text, opts) => {
        const globalOnly = !!(opts && opts.globalOnly);
        return entries.filter((e) => {
            if (!e || !e.enabled) return false;
            if (e.trigger === 'never') return false;
            const sc = normalizeScope(e.scope);
            if (globalOnly && sc !== 'global') return false;
            if (sc === 'exclusive' && e.char && charName && e.char !== charName) return false;
            if (e.trigger === 'keyword' && Array.isArray(e.keywords) && e.keywords.length) {
                const t = (text || '') + '';
                if (!e.keywords.some((k) => k && t.includes(k))) return false;
            }
            return true;
        });
    };
    // 每条目的当前状态（世界书 app 列表与生效预览共用同一口径）
    const statusOf = (e) => {
        if (!e || e.enabled === false || e.trigger === 'never') return '未启用';
        const sc = normalizeScope(e.scope);
        const base = (sc === 'exclusive') ? ('已挂载专属' + (e.char || '')) : '已挂载全局';
        if (e.trigger === 'keyword') return '关键词触发 · ' + base;
        return base;
    };
    // 记一笔：每次 buildContext/first 都记，即使 0 条也要走完这一步（不要静默跳过）
    const recordInjection = (scene, charName, hit) => {
        const rec = {
            scene: scene || '', charName: charName || '', at: Date.now(),
            titles: hit.map((e) => e.title || ''),
            entries: hit.map((e) => ({ title: e.title || '', scope: normalizeScope(e.scope), position: posLabel(e), trigger: e.trigger || 'always', content: String(e.content || '').slice(0, 60) })),
            count: hit.length
        };
        lastInjection = rec;
        try { localStorage.setItem(LAST_KEY, JSON.stringify(rec)); } catch (e) {}
        try { window.__bkLastWb = rec; } catch (e) {}
        return rec;
    };
    const getLastInjection = () => {
        if (lastInjection) return lastInjection;
        try { const raw = localStorage.getItem(LAST_KEY); if (raw) { lastInjection = JSON.parse(raw); return lastInjection; } } catch (e) {}
        return { scene: '', charName: '', titles: [], entries: [], count: 0, at: 0 };
    };
    // 世界书优先：先查世界书再生成。所有生成路径都调这个（它内部调 buildContext），不要绕过它。
    const first = (scene, charName, text) => {
        let block = '';
        try { block = api.buildContext(scene, charName, text) || ''; } catch (e) { recordInjection(scene, charName, []); }
        const li = getLastInjection();
        return { block: block, titles: (li.titles || []).slice(), count: li.count || 0, entries: li.entries || [] };
    };
    // 角色未知时只取全局条目（专属条目绝不外泄）；与 first() 一样走 buildContext（统一计数/记录口径）。
    const firstGlobal = (scene, text) => {
        let block = '';
        try { block = api.buildContext(scene, '', text, { globalOnly: true }) || ''; } catch (e) { recordInjection(scene, '', []); }
        const li = getLastInjection();
        return { block: block, titles: (li.titles || []).slice(), count: li.count || 0, entries: li.entries || [] };
    };
    // 当前生效预览：选一个角色，列出对该角色实际会注入的条目（按注入位置分组；关键词条目列出但注明需命中关键词才注入）
    const previewFor = (charName) => {
        const groups = { before: [], after: [], deep: [] };
        entries.forEach((e) => {
            if (!e || e.enabled === false || e.trigger === 'never') return;
            const sc = normalizeScope(e.scope);
            if (sc === 'exclusive' && e.char && charName && e.char !== charName) return;
            groups[posOf(e)].push({ title: e.title || '', scope: sc, char: e.char || '', position: posLabel(e), trigger: e.trigger || 'always', status: statusOf(e) });
        });
        return { charName: charName || '', groups: groups, total: groups.before.length + groups.after.length + groups.deep.length };
    };

    // ── 核心：为某个场景 + 角色构造 AI 约束上下文 ──
    // scene: 'chat' | 'moments' | 'forum' | 'cike' …（目前只用于语义标注）
    // charName: 当前活跃角色名；exclusive 条目只对匹配的角色生效
    // text: 可选，本轮用户输入/话题文本，用于 keyword 触发判定
    const buildContext = (scene, charName, text, opts) => {
        buildCount++;
        if (!entries.length) { recordInjection(scene, charName, []); return ''; }
        const hit = matchEntries(scene, charName, text, opts);
        recordInjection(scene, charName, hit);

        if (!hit.length) return '';
        // 按注入位置分组：角色前 → 角色后 → 深度注入（修复前 position 字段存了却没人用）
        const posOf = (e) => (e.position === '角色后' ? 'after' : (e.position === '深度注入' ? 'deep' : 'before'));
        const fmt = (list) => list.map(e => {
            const tag = e.title ? `《${e.title}》` : '·';
            return `${tag} ${(e.content || '').trim()}`;
        }).join('\n');
        const parts = [];
        const before = hit.filter(e => posOf(e) === 'before');
        const after = hit.filter(e => posOf(e) === 'after');
        const deep = hit.filter(e => posOf(e) === 'deep');
        if (before.length) parts.push(fmt(before));
        if (after.length) parts.push(fmt(after));
        if (deep.length) parts.push('【深度注入】\n' + fmt(deep));
        const body = parts.join('\n');
        return `\n\n【世界设定 · 你所处的世界】\n`
             + `以下是这个世界的基本设定与运行规则,你作为生活在其中的人,你的言行、认知、习惯都自然遵循这些设定。这不是约束,这是你存在的世界本身。\n`
             + body
             + `\n【世界设定结束】`;
    };

    load();
    const api = { load, save, setAll, getAll, buildContext, first, firstGlobal, matchEntries, previewFor, statusOf, normalizeScope, getLastInjection, getBuildCount: () => buildCount, get count(){ return entries.length; } };
    return api;
})();
window.WorldBook = WorldBook;

// ══════════════════════════════════════════════════════════════════════
// BackendAPI · 后端接入适配层（预留）
// ══════════════════════════════════════════════════════════════════════
// 用途：当你有自建后端时，把 enabled 改 true、填入 baseUrl/token 即可。
// 启用后，凡是调用 BackendAPI.call(path, payload) 的地方会走你的后端；
// 后端没启用时，所有调用都返回 null，调用方继续走本地/直连 API 兜底。
//
// 推荐后端 REST 端点（任选实现，不强制）：
//   POST  /v1/chat/complete       —— 微信聊天 AI 代理（屏蔽 key 给前端）
//   POST  /v1/cike/generate       —— 「此刻」内容生成
//   POST  /v1/moments/generate    —— 朋友圈生成
//   POST  /v1/forum/generate      —— 论坛贴/回复生成
//   GET   /v1/worldbook           —— 拉取云端世界书（多设备同步）
//   POST  /v1/worldbook           —— 上传/合并世界书
//   POST  /v1/album/upload        —— 此刻相册图片/内容云端备份
//   GET   /v1/user/profile        —— 当前用户人设/会话/Token 余额
//
// 任何路径都行——只要前后端约定一致。这里只做透明转发。
// ══════════════════════════════════════════════════════════════════════
const BackendAPI = (() => {
    const CFG_KEY = 'backend_api_cfg_v1';
    const DEFAULT = {
        enabled: false,            // 是否启用后端（false 时所有 call 返回 null）
        baseUrl: '',               // 例：https://your.backend.com
        token: '',                 // 鉴权 token，自动放进 Authorization: Bearer
        timeoutMs: 30000,          // 请求超时
        headers: {}                // 自定义额外请求头
    };
    let cfg = { ...DEFAULT };
    try {
        const raw = localStorage.getItem(CFG_KEY);
        if (raw) Object.assign(cfg, JSON.parse(raw));
    } catch(e) {}

    const save = () => {
        try { localStorage.setItem(CFG_KEY, JSON.stringify(cfg)); } catch(e){}
    };
    const configure = (patch) => {
        Object.assign(cfg, patch || {});
        save();
        return { ...cfg };
    };
    const isEnabled = () => !!(cfg.enabled && cfg.baseUrl);

    // 核心调用：成功返回 JSON；后端未启用返回 null；HTTP 错抛 Error
    const call = async (path, payload, method) => {
        if (!isEnabled()) return null;
        const url = cfg.baseUrl.replace(/\/+$/, '') + (path.startsWith('/') ? path : '/' + path);
        const m = (method || (payload ? 'POST' : 'GET')).toUpperCase();
        const headers = {
            'Content-Type': 'application/json',
            ...(cfg.headers || {}),
            ...(cfg.token ? { 'Authorization': 'Bearer ' + cfg.token } : {})
        };
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), cfg.timeoutMs || 30000);
        try {
            const r = await fetch(url, {
                method: m,
                headers,
                body: (m === 'GET' || m === 'HEAD') ? undefined : JSON.stringify(payload || {}),
                signal: ctrl.signal
            });
            clearTimeout(timer);
            if (!r.ok) {
                const text = await r.text().catch(() => '');
                throw new Error('HTTP ' + r.status + ' ' + text.slice(0, 200));
            }
            return await r.json();
        } catch(err) {
            clearTimeout(timer);
            console.warn('[BackendAPI] ' + path + ' 失败:', err.message);
            throw err;
        }
    };

    // ── 业务便捷封装 ──
    // 任意一个返回 null 都表示「后端未启用」，调用方应回退到本地实现
    const chatComplete = (payload) => call('/v1/chat/complete', payload);
    const cikeGenerate = (payload) => call('/v1/cike/generate', payload);
    const momentsGenerate = (payload) => call('/v1/moments/generate', payload);
    const forumGenerate = (payload) => call('/v1/forum/generate', payload);
    const worldbookPull = () => call('/v1/worldbook', null, 'GET');
    const worldbookPush = (entries) => call('/v1/worldbook', { entries });
    const albumUpload = (item) => call('/v1/album/upload', item);
    const userProfile = () => call('/v1/user/profile', null, 'GET');

    return {
        get config(){ return { ...cfg }; },
        configure, isEnabled, call,
        chatComplete, cikeGenerate, momentsGenerate, forumGenerate,
        worldbookPull, worldbookPush, albumUpload, userProfile
    };
})();
window.BackendAPI = BackendAPI;

// ══════════════════════════════════════════════════════════════════════
// SystemReset · 重置全部数据（恢复出厂）
// 一键清空 localStorage 里所有本应用的数据，刷新后回到全新空白状态。
// 解决场景：旧版有缓存数据（如默认角色「夏油杰」等），用户升级到新版
// 但 localStorage 里还存着旧 sessions，restoreWX() 把它们都恢复了。
// ══════════════════════════════════════════════════════════════════════
const SystemReset = (() => {
    // 本应用使用的所有 localStorage key 前缀（保险起见，遍历全部 key 删掉）
    const KNOWN_KEYS = [
        'phone_wechat_store_v1',       // 微信会话/朋友圈
        'phone_my_persona',            // 我的身份
        'phone_my_persona_data',       // 我的身份扩展
        'phone_chatbg_v1',             // 聊天背景
        'phone_forum_favs',            // 论坛收藏
        'worldbook_global_v1',         // 世界书
        'backend_api_cfg_v1',          // 后端API配置
        'cike_album_v1',               // 此刻相册
        'iconsystem_v1',               // 桌面图标布局
        'novel_api_key',               // 小说 API key
        'wx_moments_cover',            // 朋友圈封面
        'phone_lock_pw_v1',            // [AJ] 锁屏密码
        'phone_lock_passcode',         // [AJ] 旧锁屏密码键
        'phone_lock_disabled',         // [AJ] 旧锁屏开关
        'phone_lock_fail_v1',          // [AJ] 锁屏输错计数
        'phone_char_named_v1',         // [AJ] char 是否已命名
    ];

    const wipe = () => {
        try {
            // 删指定 key
            KNOWN_KEYS.forEach(k => localStorage.removeItem(k));
            // 兜底：把所有以 phone_ / cike_ / wx_ / wb_ 开头的 key 也删掉
            const all = Object.keys(localStorage);
            all.forEach(k => {
                if (/^(phone_|cike_|wx_|wb_|novel_|worldbook_|backend_)/.test(k)) {
                    localStorage.removeItem(k);
                }
            });
            // ★ 云端用户 ID 也清掉，下次启动会创建新用户（与旧云端数据脱钩）
            if (window.CloudDB && typeof window.CloudDB.resetUserId === 'function') {
                window.CloudDB.resetUserId();
            }
        } catch(e) { console.warn('清理 localStorage 失败', e); }
    };

    const confirm = () => {
        const ok = window.confirm(
            '将清空全部数据并恢复出厂状态：\n\n' +
            '• 微信会话、朋友圈\n' +
            '• 世界书\n' +
            '• 我的身份\n' +
            '• 聊天背景 / 此刻相册\n' +
            '• 后端 / API 配置\n' +
            '• 桌面布局\n\n' +
            '此操作无法撤销。确定继续？'
        );
        if (!ok) return;
        wipe();
        alert('已重置 即将刷新');
        setTimeout(() => { location.reload(); }, 300);
    };

    return { wipe, confirm };
})();
window.SystemReset = SystemReset;

 const SystemCore = (() => {
    return {
        boot: () => {
            console.log("小未来的手机启动");
            // ── 人格核心先于一切初始化（每步独立 try/catch：一步抛错不再拖垮整机与开屏）──
            const safeInit = (name, fn) => { try { fn(); } catch(e) { console.error('[SystemCore] 初始化失败:', name, e); } };
            safeInit('MemoryCore', () => { if (typeof MemoryCore !== 'undefined') MemoryCore.init(); });
            safeInit('CentralEngine', () => { if (typeof CentralEngine !== 'undefined') CentralEngine.start(); });
            safeInit('WorldStateEngine', () => { if (typeof WorldStateEngine !== 'undefined') WorldStateEngine.start(); });
            safeInit('TimeEngine', () => { if (typeof TimeEngine !== 'undefined') TimeEngine.start(); });
            safeInit('LockScreenEngine', () => { if (typeof LockScreenEngine !== 'undefined') LockScreenEngine.init(); });
            safeInit('GroupAJ', () => { if (typeof GroupAJ !== 'undefined') GroupAJ.boot(); });
            safeInit('DesktopEngine', () => { if (typeof DesktopEngine !== 'undefined') DesktopEngine.init(); });
            safeInit('SystemCenter', () => { if (typeof SystemCenter !== 'undefined') SystemCenter.init(); });
            safeInit('FloatBall', () => { if (typeof FloatBall !== 'undefined') FloatBall.init(); });
            // ── 同步活跃角色到 MemoryCore ──
            // [AJ] char 名默认未设置：不再强制填“夏油杰”；未设置时显示层用“TA”
            const defaultChar = (typeof SystemStore !== 'undefined' && SystemStore.get('character')) || '';
            if (defaultChar && typeof SystemStore !== 'undefined') { try { SystemStore.set('character', defaultChar); } catch(e){} }
            if (defaultChar && typeof MemoryCore !== 'undefined') { try { MemoryCore.world.set('activeChar', defaultChar); } catch(e){} }
            
            const DEFAULT_WP = ''; // [D组] 默认壁纸改为本地纯白，不再拉取外链图片
            // 本地兜底壁纸（纯 CSS 渐变，不依赖任何图床）：外链死链时不再黑屏
            const LOCAL_WP = 'linear-gradient(160deg, #ffffff 0%, #fdfcf9 55%, #f7f3ec 100%)';
            let savedWp = (typeof SystemStore !== 'undefined') ? SystemStore.get('wallpaper') : null;
            // 校验壁纸值：空 / 非法 / 'undefined' 字符串 → 回退默认
            if (!savedWp || typeof savedWp !== 'string' || savedWp === 'undefined' ||
                !(savedWp.startsWith('http') || savedWp.startsWith('data:'))) {
                savedWp = DEFAULT_WP;
            }
            const shell = document.getElementById('sys-shell');
            if (shell) {
                shell.style.backgroundImage = savedWp ? `url("${savedWp}"), ${LOCAL_WP}` : LOCAL_WP; // [D组] 无自选壁纸时只用纯白渐变
                // 壁纸加载失败时自动回退：先试默认外链，默认外链也失败则用本地渐变兜底
                const testImg = new Image();
                testImg.onerror = () => {
                    if (savedWp !== DEFAULT_WP) {
                        const testDefault = new Image();
                        testDefault.onerror = () => { shell.style.backgroundImage = LOCAL_WP; };
                        testDefault.onload = () => { shell.style.backgroundImage = `url("${DEFAULT_WP}"), ${LOCAL_WP}`; };
                        testDefault.src = DEFAULT_WP;
                    } else {
                        shell.style.backgroundImage = LOCAL_WP;
                    }
                };
                testImg.src = savedWp;
                // 锁屏壁纸（独立设置，存在才应用）
                try {
                    const lsWp = (typeof SystemStore !== 'undefined') ? SystemStore.get('lockscreen_wp') : null;
                    if (lsWp && typeof lsWp === 'string' && (lsWp.startsWith('http') || lsWp.startsWith('data:'))) {
                        const lsDom = document.getElementById('sys-lockscreen-layer');
                        if (lsDom) lsDom.style.backgroundImage = `url("${lsWp}"), ${LOCAL_WP}`;
                    }
                } catch(e){}
            }
            // 深色外观下调暗墙纸：启动后恢复用户开关
            try { if (window.BeautifyEngine && BeautifyEngine.applyWallpaperDim) BeautifyEngine.applyWallpaperDim(); } catch(e){}

            // ★ 应用美化助手 → 布局与状态栏 持久化设置
            try {
                if (window.BeautifyEngine && window.BeautifyEngine.applyLayout) {
                    window.BeautifyEngine.applyLayout();
                }
                // 启动时应用持久化的气泡自定义 CSS
                const css = localStorage.getItem('b_bubble_custom_css');
                const scope = localStorage.getItem('b_bubble_scope') || 'wechat';
                if (css) {
                    const styleId = 'b-bubble-custom-style';
                    let st = document.getElementById(styleId);
                    if (!st) { st = document.createElement('style'); st.id = styleId; document.head.appendChild(st); }
                    const sel = scope === 'all' ? '.wx-msg-bubble, .b-bubble-body, [class*="bubble"]' : '.wx-msg-bubble';
                    st.textContent = `${sel} { ${css.replace(/<\/style/gi, '')} }`;
                }
                // 启动时应用各 APP 的页面背景
                ['forum','novel','cike'].forEach(a => {
                    try { window.BeautifyEngine._applyAppBgCSS(a); } catch(e){}
                });
            } catch(e){}
            
            const appWin = document.querySelector('[data-app-sandbox="catos"]');
            if (appWin && typeof Controller !== 'undefined') {
                Controller.setupPartnerSystem(appWin);
            }
        }
    };
})();


